var INKS = ['#dc2626', '#ea580c', '#ca8a04', '#16a34a', '#0d9488', '#2563eb', '#7c3aed', '#db2777', '#6b7280', '#ffffff'];
var STYLE_KEYS = ['bg', 'fg', 'b', 'i', 'al'];
