      if (S.flash.has(k) && now - S.flash.get(k) < 1700) cl += ' fl';
      html += '<div class="' + cl + '" data-c="' + i + '" style="left:' + (GUT + S.colX[i]) + 'px;width:' + S.colW[i] + 'px;height:' + RH + 'px;' + cellStyle(f) + '">' + cellHtml(c, v, f) + '</div>';
