app.get("/api/members", async (req, res) => {
  cacheFor(res, 120);
  const data = await memCache("members:list", 120, async () => {
    const { data, error } = await supabasePublic
      .from("members")
      .select(
        "id,name,role,batch,bio,domain,photo,special_tag,sort_order,is_past,hall_of_fame,instagram,github,linkedin,twitter,youtube,website,custom_links",
      )
      .is("deleted_at", null)
      .order("sort_order", { ascending: true });

    // If social/portal columns don't exist yet, fall back to base columns
    if (error) {
      console.warn("[members] Full select failed (missing columns?), trying base columns:", error.message);
      const { data: base } = await supabase
        .from("members")
        .select("id,name,role,batch,bio,domain,photo,special_tag,sort_order,is_past")
        .is("deleted_at", null)
        .order("sort_order", { ascending: true });
      return base || [];
    }

    // If anon client returned empty (likely an RLS policy blocking reads),
    // fall back to the admin client so the public page always works
    if (!data || data.length === 0) {
      console.warn("[members] supabasePublic returned empty — falling back to admin client (check RLS on members table)");
      const { data: fallback } = await supabase
        .from("members")
        .select(
          "id,name,role,batch,bio,domain,photo,special_tag,sort_order,is_past,hall_of_fame,instagram,github,linkedin,twitter,youtube,website,custom_links",
        )
        .is("deleted_at", null)
        .order("sort_order", { ascending: true });
      return fallback || [];
    }

    return data || [];
  });

  // The "KFS" row is a sentinel account used internally for official
  // one-way broadcast DMs — it's not a real member and must never show up
  // on the public Members page.
  const kfsSentinelId = await getKfsSentinelId();
  const filtered = kfsSentinelId ? (data || []).filter(m => m.id !== kfsSentinelId) : data;
  res.json(filtered);
});

