app.post("/api/reviews", strictWriteLimit, async (req, res) => {
  const {
    movie_id,
    reviewer_name,
    overall,
    direction,
    sound,
    cinematography,
    script,
  } = req.body;
  if (!movie_id || !overall)
    return res.status(400).json({ error: "movie_id and overall are required" });

  // Validate score ranges (prevent overall:999 or overall:"DROP TABLE" etc.)
  function parseScore(val) {
    const n = parseInt(val);
    return (!isNaN(n) && n >= 1 && n <= 10) ? n : null;
  }
  const overallScore = parseScore(overall);
  if (overallScore === null)
    return res.status(400).json({ error: "overall must be an integer between 1 and 10" });

  const { data, error } = await supabasePublic
    .from("reviews")
    .insert([
      {
        movie_id,
        reviewer_name: (reviewer_name || "Anonymous").toString().replace(/[<>]/g, "").slice(0, 60),
        overall: overallScore,
        direction: parseScore(direction),
        sound: parseScore(sound),
        cinematography: parseScore(cinematography),
        script: parseScore(script),
      },
    ])
    .select()
    .single();
  if (error) return res.status(500).json({ error: "Internal server error" });
  memInvalidate(`reviews:${movie_id}`, "reviews:all");
  res.json(data);
});

// ── EVENT REGISTRATION FORMS ──────────────────────────────────────────────────
//
// Forms support branching "sections" (à la Google Forms): a form is a list of
// sections, each holding one or more questions. After a section, the form
// moves to a default "next section" — unless one of that section's
// multiple-choice questions has branching enabled, in which case the chosen
// option can route to a different section entirely (e.g. a "Participant or
// Audience?" question routing into two completely different question paths).
//
// Any section can also be flagged is_paid with a fixed amount_paise — set
// once by the admin and never customizable by the registrant. The actual
// path taken (and therefore the amount owed) is always recomputed
// server-side from the submitted answers, never trusted from the client.
//
// Storage: reuses the existing event_forms.questions TEXT column (no DB
// migration needed for this table). Shape on disk:
//   v1 (legacy, flat):  [ {id,label,type,required,options}, ... ]
//   v2 (sections):      { version: 2, sections: [ {id,title,description,
//                          questions:[...], next_section, is_paid,
//                          amount_paise}, ... ] }
// parseFormSchema() normalizes both into a uniform {version, sections} shape
// so every downstream route only has to deal with one representation.

const SUBMIT_END = "__submit__";

function parseFormSchema(rawQuestions) {
  let parsed;
  try {
    // rawQuestions may already be a parsed object (Supabase JSONB auto-parse)
    if (typeof rawQuestions === "object" && rawQuestions !== null) {
      parsed = rawQuestions;
    } else {
      parsed = JSON.parse(rawQuestions || "[]");
    }
  } catch {
    parsed = [];
  }
  if (parsed && !Array.isArray(parsed) && Array.isArray(parsed.sections)) {
    return {
      version: 2,
      sections: parsed.sections,
      // Admin-chosen question whose answer should receive the confirmation/
      // ticket email, when a form has more than one email-type question
      // (e.g. a KIIT mail + a personal mail). Falls back to the tiered
      // auto-detection in pickTargetEmail() when not set.
      targetEmailQuestionId: parsed.target_email_question_id || null,
    };
  }
  // Legacy flat array — wrap as a single implicit section so the branching
  // engine below works unchanged for old forms that haven't been rebuilt yet.
  const flat = Array.isArray(parsed) ? parsed : [];
  return {
    version: 1,
    sections: [
      {
        id: "_legacy",
        title: null,
        description: null,
        questions: flat,
        next_section: SUBMIT_END,
        is_paid: false,
        amount_paise: null,
      },
    ],
    targetEmailQuestionId: null,
  };
}

// Decide which answer becomes the "toEmail" for confirmation/ticket mail.
// Tier 0: the admin explicitly picked a question (used when a form has
//         multiple email fields, e.g. "KIIT mail" + "Personal mail").
// Tier 1: the first question explicitly typed "email".
// Tier 2: a text/textarea question whose label mentions "email".
// Tier 3: scan every answer for something that looks like an email address.
function pickTargetEmail(questions, finalAnswers, targetEmailQuestionId) {
  const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  if (targetEmailQuestionId) {
    const q = (questions || []).find((q) => q.id === targetEmailQuestionId);
    const val = q ? (finalAnswers[q.id] || "").toString().trim() : "";
    if (val) return val;
  }

  let emailQ = (questions || []).find((q) => q.type === "email");
  if (!emailQ)
    emailQ = (questions || []).find(
      (q) =>
        ["text", "textarea"].includes(q.type) &&
        /e[\s-]?mail/i.test(q.label || ""),
    );

  let toEmail = emailQ ? (finalAnswers[emailQ.id] || "").trim() : null;
  if (!toEmail) {
    for (const val of Object.values(finalAnswers)) {
      if (typeof val === "string" && EMAIL_RE.test(val.trim())) {
        toEmail = val.trim();
        break;
      }
    }
  }
  return toEmail || null;
}

// Every email-type question across a form's sections, tagged with its
// section title — used to populate the "send confirmation to" picker in the
// admin form builder whenever a form has 2+ email questions.
function collectEmailQuestions(sections) {
  const out = [];
  for (const s of sections || []) {
    for (const q of s.questions || []) {
      if (q.type === "email") out.push({ id: q.id, label: q.label || "Email", sectionTitle: s.title || "" });
    }
  }
  return out;
}

// Walk the section graph starting at sections[0], using `answers` to resolve
// any branching questions along the way. Returns the section ids actually
// visited, the flattened list of questions belonging to those sections
// (this — not the raw full schema — is what required-field validation and
// dedupe checks should run against), and the total amount owed (paise).
function computeSectionPath(sections, answers) {
  answers = answers || {};
  const byId = new Map((sections || []).map((s) => [s.id, s]));
  const visitedSectionIds = [];
  const questions = [];
  let requiredAmountPaise = 0;

  let current = (sections || [])[0] || null;
  const seen = new Set();
  let guard = 0;

  while (current && guard <= sections.length + 1) {
    guard++;
    if (seen.has(current.id)) break; // cycle guard — malformed schema
    seen.add(current.id);
    visitedSectionIds.push(current.id);
    for (const q of current.questions || []) questions.push(q);
    if (current.is_paid && Number(current.amount_paise) > 0) {
      requiredAmountPaise += Number(current.amount_paise);
    }

    // 1. A branching question's answer can override the section default.
    let nextId = null;
    for (const q of current.questions || []) {
      if (q.branch && q.branch.enabled && q.type === "radio") {
        const ans = (answers[q.id] || "").toString();
        const target = ans && q.branch.map ? q.branch.map[ans] : null;
        if (target === SUBMIT_END) nextId = SUBMIT_END;
        else if (target && byId.has(target)) nextId = target;
        if (nextId) break; // first branching question with a match wins
      }
    }

    // 2. Otherwise fall back to the section's own default next-section.
    if (nextId === null) {
      if (current.next_section === SUBMIT_END) nextId = SUBMIT_END;
      else if (current.next_section && byId.has(current.next_section))
        nextId = current.next_section;
      else {
        const idx = sections.findIndex((s) => s.id === current.id);
        nextId =
          idx >= 0 && idx + 1 < sections.length
            ? sections[idx + 1].id
            : SUBMIT_END;
      }
    }

    current = nextId === SUBMIT_END || !nextId ? null : byId.get(nextId) || null;
  }

  return { visitedSectionIds, questions, requiredAmountPaise };
}

// ADMIN-side validation when saving a sections-based form.
function validateSectionsPayload(sections) {
  if (!Array.isArray(sections) || sections.length === 0)
    return "At least one section is required";

  const sectionIds = new Set();
  for (const s of sections) {
    if (!s.id || typeof s.id !== "string") return "Each section needs an id";
    if (sectionIds.has(s.id)) return `Duplicate section id: ${s.id}`;
    sectionIds.add(s.id);
  }

  for (const s of sections) {
    if (!Array.isArray(s.questions))
      return `Section "${s.title || s.id}" needs a questions array`;
    if (s.is_paid) {
      const amt = parseInt(s.amount_paise, 10);
      if (!amt || amt < 100)
        return `Section "${s.title || s.id}" needs a payment amount of at least ₹1`;
    }
    if (
      s.next_section &&
      s.next_section !== SUBMIT_END &&
      !sectionIds.has(s.next_section)
    )
      return `Section "${s.title || s.id}" has an invalid "next section" target`;

    const qIds = new Set();
    for (const q of s.questions) {
      if (!q.id || !q.type)
        return `Each question must have id and type (section "${s.title || s.id}")`;
      if (qIds.has(q.id)) return `Duplicate question id: ${q.id}`;
      qIds.add(q.id);
      if (
        (q.type === "radio" || q.type === "checkbox") &&
        (!Array.isArray(q.options) || q.options.length < 1)
      )
        return `Question "${q.label || q.id}" needs at least 1 option`;
      if (q.branch && q.branch.enabled) {
        if (q.type !== "radio")
          return `Only multiple-choice questions can branch ("${q.label || q.id}")`;
        q.required = true; // a branching question must always be answered
        for (const target of Object.values(q.branch.map || {})) {
          if (target && target !== SUBMIT_END && !sectionIds.has(target))
            return `Question "${q.label || q.id}" branches to an unknown section`;
        }
      }
    }
  }
  return null;
}

// Public — CSRF-protected. Limits payment-order creation attempts per IP.
const eventFormPaymentLimit = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 15,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: "Too many payment attempts. Please wait 15 minutes." },
  keyGenerator: (req, res) => ipKeyGenerator(req, res),
});

// PUBLIC: Get the registration form for an event (schema only, no responses)
app.get("/api/events/:id/form", async (req, res) => {
  cacheFor(res, 120); // 2-min cache — form rarely changes
  try {
    const data = await memCache(`event:form:${req.params.id}`, 120, async () => {
      let { data, error } = await supabasePublic
        .from("event_forms")
        .select("id,event_id,title,description,questions,is_open,issues_ticket,created_at,updated_at")
        .eq("event_id", req.params.id)
        .maybeSingle();
      if (error) {
        // issues_ticket column may not exist yet (pre-migration) — retry without it.
        const retry = await supabasePublic
          .from("event_forms")
          .select("id,event_id,title,description,questions,is_open,created_at,updated_at")
          .eq("event_id", req.params.id)
          .maybeSingle();
        if (retry.error) throw new Error(retry.error.message);
        data = retry.data;
      }
      return data;
    });
    if (!data)
      return res.status(404).json({ error: "No form found for this event" });
    // Default true when the column doesn't exist yet or was never set —
    // preserves current behavior for every pre-existing form.
    res.json({ ...data, issues_ticket: data.issues_ticket !== false });
  } catch (e) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// PUBLIC: Create a Razorpay order for a paid section reached during a form.
// The amount is NEVER taken from the client — it's recomputed server-side
// from the form's branching schema plus the answers given so far, so it
// can't be tampered with by editing the request.
app.post(
  "/api/events/:id/form/create-order",
  eventFormPaymentLimit,
  csrfProtect,
  async (req, res) => {
    if (!RAZORPAY_KEY_ID || !RAZORPAY_KEY_SECRET) {
      console.error("[event-form/create-order] Razorpay env vars not configured.");
      return res
        .status(503)
        .json({ error: "Payment gateway not configured. Contact support." });
    }

    const { data: form, error: formErr } = await supabasePublic
      .from("event_forms")
      .select("id,is_open,questions")
      .eq("event_id", req.params.id)
      .maybeSingle();
    if (formErr || !form) return res.status(404).json({ error: "Form not found" });
    if (!form.is_open)
      return res.status(403).json({ error: "Registrations are currently closed" });

    const { sections } = parseFormSchema(form.questions);

    let answers = {};
    try {
      const raw = req.body.answers;
      answers = (typeof raw === "object" && raw !== null) ? raw : JSON.parse(raw || "{}");
    } catch {
      return res.status(400).json({ error: "Invalid answers payload" });
    }

    const { requiredAmountPaise } = computeSectionPath(sections, answers);
    if (!requiredAmountPaise || requiredAmountPaise <= 0) {
      return res.status(400).json({ error: "No payment is required at this step." });
    }

    try {
      // NOTE: Razorpay's `receipt` field has a hard 40-character limit.
      // Event IDs can be full UUIDs (36 chars), so "kfs_evtreg_<uuid>_<timestamp>"
      // (~61 chars) was silently rejected by Razorpay's API on every request,
      // which surfaced to users as "Could not initiate payment. Please try again."
      // Keep it short — same safe pattern as the donation flow's receipt ID.
      const receiptId = `kfs_evt_${Date.now()}`;
      const order = await createRazorpayOrder(requiredAmountPaise, receiptId);
      return res.json({
        order_id: order.id,
        key_id: RAZORPAY_KEY_ID,
        amount_paise: requiredAmountPaise,
      });
    } catch (e) {
      console.error("[event-form/create-order]", e.message);
      return res.status(502).json({ error: "Could not initiate payment. Please try again." });
    }
  },
);

// ADMIN: Create or update (upsert) the registration form for an event
app.post(

  "/api/admin/events/:id/form",
  requireSection("events"),
  async (req, res) => {
    const { title, description, sections, questions, is_open, issues_ticket, target_email_question_id } = req.body;

    // Preferred path: sections-based schema (branching + per-section payment).
    // `questions` (flat array) is still accepted for any older client code,
    // and is stored as-is — it gets wrapped into an implicit single section
    // by parseFormSchema() wherever it's read back out.
    let storedQuestionsJson;
    if (Array.isArray(sections)) {
      const err = validateSectionsPayload(sections);
      if (err) return res.status(400).json({ error: err });

      // Optional: which email question receives the confirmation/ticket
      // mail, when the form has more than one. Must reference a real
      // question of type "email" that's actually in this form.
      let targetEmailQId = null;
      if (target_email_question_id) {
        const allQuestions = sections.flatMap((s) => s.questions || []);
        const match = allQuestions.find(
          (q) => q.id === target_email_question_id && q.type === "email",
        );
        if (!match)
          return res.status(400).json({
            error: "Selected confirmation-email question was not found in this form.",
          });
        targetEmailQId = target_email_question_id;
      }
      storedQuestionsJson = JSON.stringify({ version: 2, sections, target_email_question_id: targetEmailQId });
    } else if (Array.isArray(questions)) {
      for (const q of questions) {
        if (!q.id || !q.type)
          return res
            .status(400)
            .json({ error: "Each question must have id and type" });
        if (
          (q.type === "radio" || q.type === "checkbox") &&
          (!Array.isArray(q.options) || q.options.length < 1)
        ) {
          return res
            .status(400)
            .json({ error: `Question "${q.label}" needs at least 1 option` });
        }
      }
      storedQuestionsJson = JSON.stringify(questions);
    } else {
      return res
        .status(400)
        .json({ error: "sections (or legacy questions) array is required" });
    }

    // Check if form already exists for this event
    const { data: existing } = await supabase
      .from("event_forms")
      .select("id")
      .eq("event_id", req.params.id)
      .maybeSingle();

    let data, error;
    const payload = {
      event_id: req.params.id,
      title: title || null,
      description: description || null,
      questions: storedQuestionsJson,
      is_open: is_open !== false && is_open !== "false",
      // Default true — an admin who never touches this toggle keeps getting
      // tickets exactly like before. Explicit false is the only opt-out.
      issues_ticket: issues_ticket !== false && issues_ticket !== "false",
      updated_at: new Date().toISOString(),
    };

    if (existing) {
      ({ data, error } = await supabase
        .from("event_forms")
        .update(payload)
        .eq("id", existing.id)
        .select()
        .single());
    } else {
      ({ data, error } = await supabase
        .from("event_forms")
        .insert([{ ...payload, created_at: new Date().toISOString() }])
        .select()
        .single());
    }

    // issues_ticket column may not exist yet (pre-migration) — retry once
    // without it rather than failing the whole save.
    if (error && /issues_ticket/i.test(error.message || "")) {
      const { issues_ticket: _drop, ...payloadNoTicketCol } = payload;
      if (existing) {
        ({ data, error } = await supabase
          .from("event_forms")
          .update(payloadNoTicketCol)
          .eq("id", existing.id)
          .select()
          .single());
      } else {
        ({ data, error } = await supabase
          .from("event_forms")
          .insert([{ ...payloadNoTicketCol, created_at: new Date().toISOString() }])
          .select()
          .single());
      }
    }

    if (error) return res.status(500).json({ error: "Internal server error" });

    // The public GET /api/events/:id/form route (used by both the live
    // registration page and this same admin builder when it reopens) caches
    // its result for 2 minutes. Without invalidating here, a saved form
    // (new/edited questions) stays invisible for up to 2 minutes after save.
    memInvalidate(`event:form:${req.params.id}`);

    const { data: ev } = await supabase
      .from("events")
      .select("title")
      .eq("id", req.params.id)
      .maybeSingle();
    logActivity(
      req.admin.id,
      req.admin.name,
      existing ? "update" : "create",
      "event_form",
      ev?.title || req.params.id,
    ).catch(e => console.error("[activity]", e.message));
    res.json(data);
  },
);

// ADMIN: Get all responses for an event form
app.get(
  "/api/admin/events/:id/form/responses",
  requireSection("events"),
  async (req, res) => {
    const { data, error } = await _pageAll(() => supabase
      .from("form_responses")
      .select("*")
      .eq("event_id", req.params.id)
      .order("submitted_at", { ascending: false })
      .order("id", { ascending: true }));
    if (error) return res.status(500).json({ error: "Internal server error" });
    res.json(data || []);
  },
);

// ADMIN: Delete only the responses (keeps the form schema intact)
app.delete(
  "/api/admin/events/:id/form/responses",
  requireSection("events"),
  async (req, res) => {
    const { error } = await supabase
      .from("form_responses")
      .delete()
      .eq("event_id", req.params.id);
    if (error) return res.status(500).json({ error: "Internal server error" });
    const { data: ev } = await supabase
      .from("events")
      .select("title")
      .eq("id", req.params.id)
      .maybeSingle();
    logActivity(
      req.admin.id,
      req.admin.name,
      "delete",
      "form_responses",
      `Responses for ${ev?.title || req.params.id}`,
    ).catch(e => console.error("[activity]", e.message));
    res.json({ success: true });
  },
);

// ADMIN: Delete the form for an event (and all its responses)
app.delete(
  "/api/admin/events/:id/form",
  requireSection("events"),
  async (req, res) => {
    await supabase
      .from("form_responses")
      .delete()
      .eq("event_id", req.params.id);
    await supabase.from("event_forms").delete().eq("event_id", req.params.id);
    memInvalidate(`event:form:${req.params.id}`);
    const { data: ev } = await supabase
      .from("events")
      .select("title")
      .eq("id", req.params.id)
      .maybeSingle();
    logActivity(
      req.admin.id,
      req.admin.name,
      "delete",
      "event_form",
      ev?.title || req.params.id,
    ).catch(e => console.error("[activity]", e.message));
    res.json({ success: true });
  },
);

// PUBLIC: Submit a response to an event registration form
// Handles multipart/form-data so image files can be uploaded per-question
app.post("/api/events/:id/form/submit", strictWriteLimit, upload.any(), async (req, res) => {
  // 1. Verify the form exists and is open
  let { data: form, error: formErr } = await supabasePublic
    .from("event_forms")
    .select("id,is_open,questions,issues_ticket")
    .eq("event_id", req.params.id)
    .maybeSingle();
  if (formErr) {
    // issues_ticket column may not exist yet (pre-migration) — retry without it.
    const retry = await supabasePublic
      .from("event_forms")
      .select("id,is_open,questions")
      .eq("event_id", req.params.id)
      .maybeSingle();
    form = retry.data;
    formErr = retry.error;
  }

  if (formErr || !form)
    return res.status(404).json({ error: "Form not found" });
  // Default true when the column doesn't exist yet or was never set —
  // preserves current behavior (ticket + form response) for every
  // pre-existing form that hasn't been explicitly switched off.
  const issuesTicket = form.issues_ticket !== false;
  if (!form.is_open)
    return res
      .status(403)
      .json({ error: "Registrations are currently closed" });

  // 2. Parse submitted answers
  let answers = {};
  try {
    answers = JSON.parse(req.body.answers || "{}");
  } catch (e) {
    return res.status(400).json({ error: "Invalid answers payload" });
  }

  // 3. Recompute the actual path taken through the form's sections from the
  //    submitted answers (never trust a client-reported path). `questions`
  //    below is the flattened set of questions belonging only to the
  //    sections actually visited — branches not taken are correctly ignored
  //    for both required-field validation and the fee that's owed.
  const { sections, targetEmailQuestionId } = parseFormSchema(form.questions);
  const { questions, requiredAmountPaise } = computeSectionPath(sections, answers);

  for (const q of questions) {
    if (!q.required) continue;
    if (q.type === "image") {
      const hasFile = (req.files || []).some((f) => f.fieldname === q.id);
      if (!hasFile)
        return res
          .status(400)
          .json({ error: `"${q.label || q.id}" is required` });
    } else {
      const val = answers[q.id];
      const isEmpty =
        val === undefined ||
        val === null ||
        val === "" ||
        (Array.isArray(val) && val.length === 0);
      if (isEmpty)
        return res
          .status(400)
          .json({ error: `"${q.label || q.id}" is required` });
    }
  }

  // 3a. Payment verification — only when the visited path crossed a paid
  //     section. The amount is whatever computeSectionPath() determined
  //     server-side; the client cannot influence it.
  let paymentRecord = null;
  if (requiredAmountPaise > 0) {
    let payment = null;
    try {
      payment = JSON.parse(req.body.payment || "null");
    } catch {}
    const { razorpay_order_id, razorpay_payment_id, razorpay_signature } = payment || {};

    if (!razorpay_order_id || !razorpay_payment_id || !razorpay_signature)
      return res
        .status(402)
        .json({ error: "Payment is required to complete this registration." });
    if (!RAZORPAY_KEY_SECRET)
      return res.status(503).json({ error: "Payment gateway not configured." });

    // Idempotency — if this order was already recorded, don't double-submit
    const { data: existingPay } = await supabase
      .from("form_responses")
      .select("id")
      .eq("razorpay_order_id", razorpay_order_id)
      .maybeSingle();
    if (existingPay) {
      return res.json({ success: true, duplicate: true, id: existingPay.id });
    }

    // HMAC-SHA256 signature check (same scheme as the donation flow)
    const sigBody = `${razorpay_order_id}|${razorpay_payment_id}`;
    const expectedSig = crypto
      .createHmac("sha256", RAZORPAY_KEY_SECRET)
      .update(sigBody)
      .digest("hex");
    let sigValid = false;
    try {
      sigValid = crypto.timingSafeEqual(
        Buffer.from(expectedSig),
        Buffer.from(razorpay_signature),
      );
    } catch {
      sigValid = false;
    }
    if (!sigValid) {
      console.warn("[event-form/submit] Signature mismatch for order:", razorpay_order_id);
      supabase.from("payment_failures").insert([{
        razorpay_order_id,
        razorpay_payment_id,
        failure_reason: "invalid_signature_event_registration",
        ip_address: req.ip,
        user_agent: req.headers["user-agent"] || null,
      }]).then(({ error }) => {
        if (error) console.warn("[event-form/submit] Could not log failure:", error.message);
      });
      return res.status(400).json({ error: "Payment verification failed. Signature mismatch." });
    }

    // Confirm the amount actually paid via Razorpay — never trust the client.
    let paidAmountPaise = null;
    try {
      const auth = Buffer.from(`${RAZORPAY_KEY_ID}:${RAZORPAY_KEY_SECRET}`).toString("base64");
      const payRes = await fetch(`https://api.razorpay.com/v1/payments/${razorpay_payment_id}`, {
        headers: { Authorization: `Basic ${auth}` },
      });
      const payData = await payRes.json();
      if (payRes.ok && payData.amount) paidAmountPaise = payData.amount;
    } catch (e) {
      console.warn("[event-form/submit] Could not fetch payment amount from Razorpay:", e.message);
    }
    if (paidAmountPaise !== null && paidAmountPaise !== requiredAmountPaise) {
      console.warn(`[event-form/submit] Amount mismatch: expected ${requiredAmountPaise}, paid ${paidAmountPaise}`);
      return res
        .status(400)
        .json({ error: "Payment amount does not match the required registration fee." });
    }

    paymentRecord = {
      amount_paise: paidAmountPaise || requiredAmountPaise,
      razorpay_order_id,
      razorpay_payment_id,
      razorpay_signature,
      payment_verified_at: new Date().toISOString(),
    };
  }

  // 3b. Duplicate check — block if same email or phone already submitted for this event
  const dedupeTypes = ["email", "phone"];
  const dedupeKeys = questions
    .filter((q) => dedupeTypes.includes(q.type))
    .map((q) => ({ id: q.id, label: q.label || q.type, type: q.type }));

  if (dedupeKeys.length > 0) {
    // Fetch existing responses for this event
    const { data: existing } = await _pageAll(() => supabase
      .from("form_responses")
      .select("answers")
      .eq("event_id", req.params.id)
      .order("id", { ascending: true }));

    for (const key of dedupeKeys) {
      const submitted = (answers[key.id] || "").trim().toLowerCase();
      if (!submitted) continue;
      const isDup = (existing || []).some((row) => {
        try {
          const prev = JSON.parse(row.answers || "{}");
          return (prev[key.id] || "").trim().toLowerCase() === submitted;
        } catch {
          return false;
        }
      });
      if (isDup) {
        const label = key.type === "email" ? "Email" : "Mobile number";
        return res
          .status(409)
          .json({ error: `${label} already registered for this event.` });
      }
    }
  }

  // 4. Upload any image files to Supabase Storage
  const imageUrls = {};
  for (const file of req.files || []) {
    try {
      const url = await uploadImage(file, `form-responses/${req.params.id}`);
      imageUrls[file.fieldname] = url;
    } catch (e) {
      console.error(
        "Image upload error for question",
        file.fieldname,
        e.message,
      );
      return res
        .status(500)
        .json({ error: "Image upload failed: " + e.message });
    }
  }

  // 5. Merge image URLs into answers
  const finalAnswers = { ...answers, ...imageUrls };

  // 6. Store response — use admin client (service_role) so this works regardless of RLS policy on form_responses
  const { data: response, error: insertErr } = await supabase
    .from("form_responses")
    .insert([
      {
        event_id: req.params.id,
        form_id: form.id,
        answers: JSON.stringify(finalAnswers),
        submitted_at: new Date().toISOString(),
        ...(paymentRecord || {}),
      },
    ])
    .select()
    .single();

  if (insertErr) return res.status(500).json({ error: "Internal server error" });
  if (global.__ksLive) global.__ksLive.notify("event", req.params.id);

  // 7. Send confirmation email (non-blocking — never fail the response)
  try {
    let toEmail = pickTargetEmail(questions, finalAnswers, targetEmailQuestionId);

    // Name: prefer a question labelled 'name', fall back to first short-text answer
    const nameQ = questions.find(
      (q) =>
        ["text", "textarea"].includes(q.type) &&
        /\bname\b/i.test(q.label || ""),
    );
    const toName = nameQ ? (finalAnswers[nameQ.id] || "").trim() : null;

    if (toEmail) {
      // Fetch event details for the email
      const { data: ev } = await supabasePublic
        .from("events")
        .select("id,title,event_date,location,location_link,whatsapp_group_link,is_upcoming")
        .eq("id", req.params.id)
        .maybeSingle();

      // ── Create event_registrations row + send QR ticket ──────────────────
      // Only when this form is configured to issue tickets. Pure feedback/
      // survey forms (issues_ticket=false) just get a plain confirmation —
      // no scanner entry, no QR.
      if (ev && toEmail && issuesTicket) {
        // v-RP: AWAIT the ticket row (fast DB work only). Emails stay async.
        await (async () => {
          try {
            const EMAIL_NORM = toEmail.toLowerCase().trim();
            // Check if already in event_registrations (avoid duplicate on re-submit)
            const { data: existing } = await supabase
              .from("event_registrations")
              .select("id, qr_token")
              .eq("event_id", ev.id)
              .eq("email", EMAIL_NORM)
              .maybeSingle();

            let reg = existing;
            let qrDataUrl;

            if (!reg) {
              // Generate QR token
              const qrToken = crypto.randomUUID();
              const QRCode = require("qrcode");
              qrDataUrl = await QRCode.toDataURL(qrToken, {
                width: 400, margin: 3,
                color: { dark: "#000000", light: "#ffffff" },
                errorCorrectionLevel: "M",
              });
              const _phoneQ = questions.find(q => q.type === "phone" || (["text","textarea"].includes(q.type) && /phone|mobile/i.test(q.label || "")));
              const _rollQ  = questions.find(q => ["text","textarea"].includes(q.type) && /roll|reg(istration)?\s*(no|number|#)/i.test(q.label || ""));
              const _regRow = {
                event_id: ev.id,
                name:     (toName || toEmail).trim(),
                email:    EMAIL_NORM,
                phone:    _phoneQ ? ((finalAnswers[_phoneQ.id] || "").toString().trim() || null) : null,
                roll_no:  _rollQ  ? ((finalAnswers[_rollQ.id]  || "").toString().trim().toUpperCase() || null) : null,
                qr_token: qrToken,
                created_at: new Date().toISOString(),
              };
              let inserted = null, insErr = null;
              for (let attempt = 0; attempt < 3 && !inserted; attempt++) {
                ({ data: inserted, error: insErr } = await supabase
                  .from("event_registrations").insert([_regRow]).select().single());
                if (!insErr) break;
                if (/phone|roll_no/.test(insErr.message || "")) { delete _regRow.phone; delete _regRow.roll_no; continue; }
                if (insErr.code === "23505") {
                  const { data: ex } = await supabase.from("event_registrations").select("*")
                    .eq("event_id", ev.id).eq("email", EMAIL_NORM).maybeSingle();
                  if (ex) { inserted = ex; insErr = null; }
                  break;
                }
                await new Promise(r => setTimeout(r, 300 * (attempt + 1)));
              }
              if (insErr || !inserted) {
                console.error("[form-submit] event_registrations insert failed:", insErr ? insErr.message : "unknown");
                // Fall back to plain confirmation email
                sendConfirmationEmail({ toEmail, toName, eventTitle: ev.title || "", eventDate: ev.event_date || null, eventVenue: ev.location || null, eventId: ev.id })
                  .catch(e => console.error("[email] confirmation fallback failed:", e.message));
                return;
              }
              reg = inserted;
              if (reg.qr_token !== qrToken) {
                qrDataUrl = await QRCode.toDataURL(reg.qr_token, {
                  width: 400, margin: 3, color: { dark: "#000000", light: "#ffffff" }, errorCorrectionLevel: "M",
                });
              }
              console.log(`[form-submit] Created event_registrations row reg_id=${reg.id} for form response`);
            } else {
              // Already registered — regenerate QR from existing token
              const QRCode = require("qrcode");
              qrDataUrl = await QRCode.toDataURL(reg.qr_token, {
                width: 400, margin: 3,
                color: { dark: "#000000", light: "#ffffff" },
                errorCorrectionLevel: "M",
              });
              console.log(`[form-submit] event_registrations row already exists reg_id=${reg.id} — resending ticket`);
            }

            // Send QR ticket email
            sendTicketEmail({ event: ev, reg, qrDataUrl })
              .catch(e => console.error("[form-submit] ticket email failed:", e.message));

            // If this registration was paid, also send the Razorpay receipt PDF
            if (paymentRecord) {
              sendPaymentBill({
                type:            "REGISTRATION",
                donorId:         null,
                recipientEmail:  toEmail,
                recipientName:   toName,
                isAnonymous:     false,
                cause:           ev.title || "Event Registration",
                amountPaise:     paymentRecord.amount_paise,
                paymentId:       paymentRecord.razorpay_payment_id,
                orderId:         paymentRecord.razorpay_order_id,
                paymentDateTime: paymentRecord.payment_verified_at,
              }).catch(e => console.error("[form-submit] payment bill email failed:", e.message));
            }
          } catch (e) {
            console.error("[form-submit] registration+ticket flow error:", e.message);
            // Fallback: send plain confirmation
            sendConfirmationEmail({ toEmail, toName, eventTitle: ev?.title || "", eventDate: ev?.event_date || null, eventVenue: ev?.location || null, eventId: ev?.id })
              .catch(err => console.error("[email] send failed:", err.message));
          }
        })();
      } else {
        // No event details, no email, or this form doesn't issue tickets —
        // send plain confirmation at minimum.
        sendConfirmationEmail({
          toEmail,
          toName,
          eventTitle: ev?.title || "",
          eventDate: ev?.event_date || null,
          eventVenue: ev?.location || null,
          eventId: ev?.id,
        }).catch((e) => console.error("[email] send failed:", e.message));

        // Paid but ticket-less form (e.g. a paid workshop feedback/entry
        // form that doesn't need a scanner QR) — still send the receipt.
        if (paymentRecord && toEmail) {
          sendPaymentBill({
            type:            "REGISTRATION",
            donorId:         null,
            recipientEmail:  toEmail,
            recipientName:   toName,
            isAnonymous:     false,
            cause:           ev?.title || "Event Registration",
            amountPaise:     paymentRecord.amount_paise,
            paymentId:       paymentRecord.razorpay_payment_id,
            orderId:         paymentRecord.razorpay_order_id,
            paymentDateTime: paymentRecord.payment_verified_at,
          }).catch(e => console.error("[form-submit] payment bill email failed:", e.message));
        }
      }
    }
  } catch (e) {
    console.error("[email] pre-send error:", e.message);
  }

  res.json({ success: true, id: response.id, amount_paise: paymentRecord?.amount_paise || 0 });
});

// ─────────────────────────────────────────────────────────────────────────────
// SECTION EF — Edit My Registration: OTP-gated, one-time edit of a form response
//
// SQL migration (run once in Supabase):
//
//   ALTER TABLE form_responses ADD COLUMN IF NOT EXISTS edit_locked BOOLEAN NOT NULL DEFAULT FALSE;
//   ALTER TABLE form_responses ADD COLUMN IF NOT EXISTS edited_at TIMESTAMPTZ;
//
//   CREATE TABLE IF NOT EXISTS form_response_edit_otps (
//     id                     UUID PRIMARY KEY DEFAULT gen_random_uuid(),
//     form_response_id       UUID NOT NULL REFERENCES form_responses(id) ON DELETE CASCADE,
//     event_id               UUID NOT NULL,
//     email_norm             TEXT NOT NULL,
//     otp_hash               TEXT NOT NULL,
//     attempts                INT NOT NULL DEFAULT 0,
//     max_attempts            INT NOT NULL DEFAULT 5,
//     expires_at              TIMESTAMPTZ NOT NULL,
//     verified_at             TIMESTAMPTZ,
//     edit_token_hash         TEXT,
//     edit_token_expires_at   TIMESTAMPTZ,
//     used_at                 TIMESTAMPTZ,
//     created_at              TIMESTAMPTZ NOT NULL DEFAULT NOW()
//   );
//   CREATE INDEX IF NOT EXISTS idx_edit_otps_response ON form_response_edit_otps(form_response_id);
//   ALTER TABLE form_response_edit_otps DISABLE ROW LEVEL SECURITY; -- server uses service_role key
// ─────────────────────────────────────────────────────────────────────────────

const EDIT_OTP_TTL_MS   = 10 * 60 * 1000; // 10 min to enter the OTP
const EDIT_TOKEN_TTL_MS = 20 * 60 * 1000; // 20 min to finish editing once verified

function hashEditToken(token) {
  return crypto.createHash("sha256").update(token).digest("hex");
}

// ids of every question whose value must NEVER change during an edit —
// email-type questions, plus any text/textarea question whose label mentions
// "name". Enforced server-side regardless of what the client submits.
function locateUneditableQuestionIds(questions) {
  const ids = new Set();
  for (const q of questions) {
    if (q.type === "email") ids.add(q.id);
    if (["text", "textarea"].includes(q.type) && /\bname\b/i.test(q.label || "")) ids.add(q.id);
  }
  return ids;
}

const editOtpLimit = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 8,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: "Too many requests. Please wait 15 minutes and try again." },
  keyGenerator: (req, res) => ipKeyGenerator(req, res),
});

// PUBLIC: Step 1 — name + any ONE registered email -> OTP sent if a match
// exists. Always returns the same generic message either way, so this can't
// be used to enumerate who registered for an event.
app.post("/api/events/:id/form/edit/request-otp", editOtpLimit, async (req, res) => {
  const GENERIC = { success: true, message: "If those details match a registration, we've sent a verification code to the registered email." };
  try {
    const name = (req.body.name || "").trim();
    const email = (req.body.email || "").trim().toLowerCase();
    if (!name || !email) return res.status(400).json({ error: "Name and email are required" });

    const { data: form } = await supabasePublic
      .from("event_forms")
      .select("id,questions")
      .eq("event_id", req.params.id)
      .maybeSingle();
    if (!form) return res.json(GENERIC);

    const { sections } = parseFormSchema(form.questions);
    const allQuestions = sections.flatMap((s) => s.questions || []);
    const emailQIds = allQuestions.filter((q) => q.type === "email").map((q) => q.id);
    const nameQIds = allQuestions
      .filter((q) => ["text", "textarea"].includes(q.type) && /\bname\b/i.test(q.label || ""))
      .map((q) => q.id);
    if (!emailQIds.length) return res.json(GENERIC);

    const { data: responses } = await supabase
      .from("form_responses")
      .select("id, answers")
      .eq("event_id", req.params.id);

    let match = null;
    for (const row of responses || []) {
      let ans;
      try { ans = JSON.parse(row.answers || "{}"); } catch { continue; }
      // "we have taken multiple mails, check any one is fine" — a hit on ANY
      // email-type question for this response counts as a match.
      const emailHit = emailQIds.some((qid) => (ans[qid] || "").trim().toLowerCase() === email);
      if (!emailHit) continue;
      const nameHit = nameQIds.length
        ? nameQIds.some((qid) => (ans[qid] || "").trim().toLowerCase() === name.toLowerCase())
        : true; // form has no explicit name question — email match alone is enough
      if (nameHit) { match = row; break; }
    }
    if (!match) return res.json(GENERIC);

    const otp = generateOtp();
    const { error: insErr } = await supabase.from("form_response_edit_otps").insert([{
      form_response_id: match.id,
      event_id: req.params.id,
      email_norm: email,
      otp_hash: hashOtp(otp),
      expires_at: new Date(Date.now() + EDIT_OTP_TTL_MS).toISOString(),
    }]);
    if (insErr) { console.error("[edit/request-otp] insert:", insErr.message); return res.json(GENERIC); }

    sendOtpViaEmail(email, name, otp).catch((e) => console.error("[edit/request-otp] send:", e.message));
    res.json(GENERIC);
  } catch (e) {
    console.error("[edit/request-otp]", e.message);
    res.json(GENERIC);
  }
});

// PUBLIC: Step 2 — verify the OTP -> returns an edit token + the previously
// submitted answers so the client can pre-fill the form.
app.post("/api/events/:id/form/edit/verify-otp", editOtpLimit, async (req, res) => {
  try {
    const email = (req.body.email || "").trim().toLowerCase();
    const code = (req.body.otp || "").trim();
    if (!email || !code) return res.status(400).json({ error: "Email and code are required" });

    const { data: otpRow } = await supabase
      .from("form_response_edit_otps")
      .select("*")
      .eq("event_id", req.params.id)
      .eq("email_norm", email)
      .is("used_at", null)
      .order("created_at", { ascending: false })
      .limit(1)
      .maybeSingle();

    if (!otpRow) return res.status(400).json({ error: "Invalid or expired code. Please request a new one." });
    if (new Date(otpRow.expires_at) < new Date())
      return res.status(400).json({ error: "Code has expired. Please request a new one." });
    if (otpRow.attempts >= otpRow.max_attempts)
      return res.status(429).json({ error: "Too many incorrect attempts. Please request a new code." });

    if (hashOtp(code) !== otpRow.otp_hash) {
      await supabase.from("form_response_edit_otps").update({ attempts: otpRow.attempts + 1 }).eq("id", otpRow.id);
      return res.status(400).json({ error: "Incorrect code." });
    }

    const { data: response } = await supabase
      .from("form_responses")
      .select("id, answers, edit_locked")
      .eq("id", otpRow.form_response_id)
      .maybeSingle();
    if (!response) return res.status(404).json({ error: "Registration not found." });

    const editToken = crypto.randomBytes(24).toString("hex");
    await supabase.from("form_response_edit_otps").update({
      verified_at: new Date().toISOString(),
      edit_token_hash: hashEditToken(editToken),
      edit_token_expires_at: new Date(Date.now() + EDIT_TOKEN_TTL_MS).toISOString(),
    }).eq("id", otpRow.id);

    if (response.edit_locked) {
      return res.json({
        success: true,
        locked: true,
        message: "This registration has already been edited once. Please contact the organisers if you need further changes.",
      });
    }

    const { data: form } = await supabasePublic
      .from("event_forms")
      .select("questions")
      .eq("event_id", req.params.id)
      .maybeSingle();
    const { sections } = parseFormSchema(form?.questions);
    const allQuestions = sections.flatMap((s) => s.questions || []);
    const uneditableIds = Array.from(locateUneditableQuestionIds(allQuestions));

    let prevAnswers = {};
    try { prevAnswers = JSON.parse(response.answers || "{}"); } catch {}

    res.json({
      success: true,
      locked: false,
      edit_token: editToken,
      answers: prevAnswers,
      uneditable_question_ids: uneditableIds,
    });
  } catch (e) {
    console.error("[edit/verify-otp]", e.message);
    res.status(500).json({ error: "Internal server error" });
  }
});

// PUBLIC: Step 3 — submit edited answers using the edit token from step 2.
// Name/email fields are always forced back to their original values
// server-side, no matter what the client sends. One successful edit
// permanently locks the response (edit_locked) — an admin can clear the
// lock from the dashboard if the registrant needs to edit again.
app.post("/api/events/:id/form/edit/submit", strictWriteLimit, upload.any(), async (req, res) => {
  try {
    const editToken = (req.body.edit_token || "").trim();
    if (!editToken) return res.status(400).json({ error: "Missing edit session. Please verify your email again." });

    const { data: otpRow } = await supabase
      .from("form_response_edit_otps")
      .select("*")
      .eq("event_id", req.params.id)
      .eq("edit_token_hash", hashEditToken(editToken))
      .is("used_at", null)
      .maybeSingle();
    if (!otpRow) return res.status(400).json({ error: "Edit session not found. Please verify your email again." });
    if (!otpRow.verified_at) return res.status(400).json({ error: "Please verify the code first." });
    if (new Date(otpRow.edit_token_expires_at) < new Date())
      return res.status(400).json({ error: "Edit session expired. Please verify your email again." });

    const { data: response } = await supabase
      .from("form_responses")
      .select("id, answers, edit_locked")
      .eq("id", otpRow.form_response_id)
      .maybeSingle();
    if (!response) return res.status(404).json({ error: "Registration not found." });
    if (response.edit_locked)
      return res.status(409).json({ error: "This registration has already been edited once. Contact the organisers for further changes." });

    let answers = {};
    try { answers = JSON.parse(req.body.answers || "{}"); } catch { return res.status(400).json({ error: "Invalid answers payload" }); }

    const { data: form } = await supabasePublic
      .from("event_forms")
      .select("id,questions")
      .eq("event_id", req.params.id)
      .maybeSingle();
    if (!form) return res.status(404).json({ error: "Form not found" });
    const { sections } = parseFormSchema(form.questions);

    let prevAnswers = {};
    try { prevAnswers = JSON.parse(response.answers || "{}"); } catch {}

    // Name/email are locked — whatever was previously stored always wins.
    const allQuestions = sections.flatMap((s) => s.questions || []);
    const uneditableIds = locateUneditableQuestionIds(allQuestions);
    for (const qid of uneditableIds) answers[qid] = prevAnswers[qid];

    const { questions } = computeSectionPath(sections, answers);
    for (const q of questions) {
      if (!q.required) continue;
      if (q.type === "image") {
        const hasFile = (req.files || []).some((f) => f.fieldname === q.id);
        const hasExisting = !!prevAnswers[q.id];
        if (!hasFile && !hasExisting) return res.status(400).json({ error: `"${q.label || q.id}" is required` });
      } else {
        const val = answers[q.id];
        const isEmpty = val === undefined || val === null || val === "" || (Array.isArray(val) && val.length === 0);
        if (isEmpty) return res.status(400).json({ error: `"${q.label || q.id}" is required` });
      }
    }

    const imageUrls = {};
    for (const file of req.files || []) {
      try {
        imageUrls[file.fieldname] = await uploadImage(file, `form-responses/${req.params.id}`);
      } catch (e) {
        return res.status(500).json({ error: "Image upload failed: " + e.message });
      }
    }

    const finalAnswers = { ...prevAnswers, ...answers, ...imageUrls };
    for (const qid of uneditableIds) finalAnswers[qid] = prevAnswers[qid];

    const { error: updErr } = await supabase
      .from("form_responses")
      .update({
        answers: JSON.stringify(finalAnswers),
        edit_locked: true,
        edited_at: new Date().toISOString(),
      })
      .eq("id", response.id);
    if (updErr) return res.status(500).json({ error: "Internal server error" });

    await supabase.from("form_response_edit_otps").update({ used_at: new Date().toISOString() }).eq("id", otpRow.id);
    if (global.__ksLive) global.__ksLive.notify("event", req.params.id);

    res.json({ success: true });
  } catch (e) {
    console.error("[edit/submit]", e.message);
    res.status(500).json({ error: "Internal server error" });
  }
});

// ADMIN: Reset the edit lock on a single response so the registrant can edit again
app.post(
  "/api/admin/events/:id/form/responses/:responseId/reset-edit-lock",
  requireSection("events"),
  async (req, res) => {
    const { error } = await supabase
      .from("form_responses")
      .update({ edit_locked: false, edited_at: null })
      .eq("id", req.params.responseId)
      .eq("event_id", req.params.id);
    if (error) return res.status(500).json({ error: "Internal server error" });
    logActivity(
      req.admin.id,
      req.admin.name,
      "update",
      "form_response_edit_lock",
      `Reset edit lock for response ${req.params.responseId}`,
    ).catch((e) => console.error("[activity]", e.message));
    res.json({ success: true });
  },
);

// ADMIN: Download responses as server-side JSON (client does XLSX conversion)
// This is an alias for the GET responses endpoint used by the download button
app.get(
  "/api/admin/events/:id/form/export",
  requireSection("events"),
  async (req, res) => {
    const { data: form } = await supabase
      .from("event_forms")
      .select("title,questions")
      .eq("event_id", req.params.id)
      .maybeSingle();

    const { data: responses } = await supabase
      .from("form_responses")
      .select("*")
      .eq("event_id", req.params.id)
      .order("submitted_at", { ascending: true });

    res.json({ form: form || null, responses: responses || [] });
  },
);

// ─────────────────────────────────────────────────────────────────────────────
// SECTION SF — Standalone Forms (not tied to any event)
//
// Same schema/branching/payment engine as event forms (parseFormSchema,
// computeSectionPath, validateSectionsPayload, pickTargetEmail — all reused
// as-is), but reachable at its own shareable link instead of living under an
// event. No QR ticket / check-in concept applies here since there's no event
// to check into — a submission just gets a confirmation email (and a payment
// receipt if a section required payment).
//
// SQL migration (run once in Supabase):
//
//   CREATE TABLE IF NOT EXISTS standalone_forms (
//     id                        UUID PRIMARY KEY DEFAULT gen_random_uuid(),
//     slug                      TEXT UNIQUE NOT NULL,
//     title                     TEXT,
//     description               TEXT,
//     questions                 TEXT NOT NULL,   -- JSON: {version:2, sections, target_email_question_id}
//     is_open                   BOOLEAN NOT NULL DEFAULT TRUE,
//     whatsapp_group_link       TEXT,            -- optional; shown as a "Join our WhatsApp Group"
//                                                 -- button on the Thank You screen after submit
//     created_at                TIMESTAMPTZ NOT NULL DEFAULT NOW(),
//     updated_at                TIMESTAMPTZ NOT NULL DEFAULT NOW()
//   );
//   CREATE INDEX IF NOT EXISTS idx_standalone_forms_slug ON standalone_forms(slug);
//   ALTER TABLE standalone_forms DISABLE ROW LEVEL SECURITY; -- server uses service_role key
//
//   -- If the table already exists (e.g. before this feature), just add the column:
//   ALTER TABLE standalone_forms ADD COLUMN IF NOT EXISTS whatsapp_group_link TEXT;
//
//   CREATE TABLE IF NOT EXISTS standalone_form_responses (
//     id                        UUID PRIMARY KEY DEFAULT gen_random_uuid(),
//     form_id                   UUID NOT NULL REFERENCES standalone_forms(id) ON DELETE CASCADE,
//     answers                   TEXT NOT NULL,
//     amount_paise              INT,
//     razorpay_order_id         TEXT,
//     razorpay_payment_id       TEXT,
//     razorpay_signature        TEXT,
//     payment_verified_at       TIMESTAMPTZ,
//     submitted_at              TIMESTAMPTZ NOT NULL DEFAULT NOW()
//   );
//   CREATE INDEX IF NOT EXISTS idx_standalone_form_responses_form ON standalone_form_responses(form_id);
//   ALTER TABLE standalone_form_responses DISABLE ROW LEVEL SECURITY; -- server uses service_role key
// ─────────────────────────────────────────────────────────────────────────────

// Public — CSRF-protected. Mirrors eventFormPaymentLimit for standalone forms.
const standaloneFormPaymentLimit = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 15,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: "Too many payment attempts. Please wait 15 minutes." },
  keyGenerator: (req, res) => ipKeyGenerator(req, res),
});

// Turns a title into a short, unique, URL-friendly slug — e.g.
// "Alumni Meet Feedback" -> "alumni-meet-feedback-4f2a". Retries with a new
// random suffix on the rare collision.
async function generateFormSlug(title) {
  const base = slugify(title || "form") || "form";
  for (let i = 0; i < 6; i++) {
    const suffix = crypto.randomBytes(3).toString("hex"); // 6 hex chars
    const slug = `${base}-${suffix}`;
    const { data } = await supabase
      .from("standalone_forms")
      .select("id")
      .eq("slug", slug)
      .maybeSingle();
    if (!data) return slug;
  }
  // Extremely unlikely fallback — fully random slug.
  return `${base}-${crypto.randomBytes(5).toString("hex")}`;
}

// ADMIN: List all standalone forms (with response counts)
app.get("/api/admin/forms", requireSection("forms"), async (req, res) => {
  const { data: forms, error } = await supabase
    .from("standalone_forms")
    // NOTE: `questions` must be included here — the admin Forms table's EDIT
    // button passes this row straight into openStandaloneFormBuilder(), which
    // reads form.questions to rebuild the sections. Without it, reopening a
    // form via EDIT showed title/description fine but every section came back
    // empty ("No questions yet"), even though the DB copy was untouched.
    .select("id,slug,title,description,questions,is_open,created_at,updated_at")
    .order("created_at", { ascending: false });
  if (error) return res.status(500).json({ error: "Internal server error" });

  const { data: counts } = await supabase
    .from("standalone_form_responses")
    .select("form_id");
  const countMap = {};
  (counts || []).forEach((r) => { countMap[r.form_id] = (countMap[r.form_id] || 0) + 1; });

  res.json((forms || []).map((f) => ({ ...f, response_count: countMap[f.id] || 0 })));
});

// ADMIN: Create a new standalone form (starts empty — admin fills it in via the builder)
app.post("/api/admin/forms", requireSection("forms"), async (req, res) => {
  const title = (req.body?.title || "Untitled Form").trim().slice(0, 200);
  const slug = await generateFormSlug(title);
  const emptySchema = JSON.stringify({
    version: 2,
    sections: [{ id: "sec_" + Date.now(), title: "", description: "", questions: [], next_section: "", is_paid: false, amount_paise: null }],
    target_email_question_id: null,
  });
  const { data, error } = await supabase
    .from("standalone_forms")
    .insert([{ slug, title, description: null, questions: emptySchema, is_open: true, created_at: new Date().toISOString(), updated_at: new Date().toISOString() }])
    .select()
    .single();
  if (error) return res.status(500).json({ error: "Internal server error" });
  logActivity(req.admin.id, req.admin.name, "create", "standalone_form", title).catch((e) => console.error("[activity]", e.message));
  res.json(data);
});

// ADMIN: Fetch one standalone form (full schema) for editing
app.get("/api/admin/forms/:id", requireSection("forms"), async (req, res) => {
  const { data, error } = await supabase
    .from("standalone_forms")
    .select("*")
    .eq("id", req.params.id)
    .maybeSingle();
  if (error || !data) return res.status(404).json({ error: "Form not found" });
  res.json(data);
});

// ADMIN: Update a standalone form's schema/settings
app.post("/api/admin/forms/:id", requireSection("forms"), async (req, res) => {
  const { title, description, sections, is_open, target_email_question_id, whatsapp_group_link } = req.body;
  if (!Array.isArray(sections)) return res.status(400).json({ error: "sections array is required" });
  const err = validateSectionsPayload(sections);
  if (err) return res.status(400).json({ error: err });

  let targetEmailQId = null;
  if (target_email_question_id) {
    const allQuestions = sections.flatMap((s) => s.questions || []);
    const match = allQuestions.find((q) => q.id === target_email_question_id && q.type === "email");
    if (!match) return res.status(400).json({ error: "Selected confirmation-email question was not found in this form." });
    targetEmailQId = target_email_question_id;
  }

  const storedQuestionsJson = JSON.stringify({ version: 2, sections, target_email_question_id: targetEmailQId });
  const { data, error } = await supabase
    .from("standalone_forms")
    .update({
      title: (title || "Untitled Form").trim().slice(0, 200),
      description: description || null,
      questions: storedQuestionsJson,
      is_open: is_open !== false && is_open !== "false",
      whatsapp_group_link: whatsapp_group_link ? String(whatsapp_group_link).trim().slice(0, 500) : null,
      updated_at: new Date().toISOString(),
    })
    .eq("id", req.params.id)
    .select()
    .single();
  if (error) return res.status(500).json({ error: "Internal server error" });
  // Same 2-minute stale-cache issue as the event form route above — the
  // public GET /api/forms/:slug endpoint caches by slug, so invalidate it
  // here or a saved edit won't show up on the live shareable link for a while.
  memInvalidate(`standalone-form:${data.slug}`);
  logActivity(req.admin.id, req.admin.name, "update", "standalone_form", data.title || req.params.id).catch((e) => console.error("[activity]", e.message));
  res.json(data);
});

// ADMIN: Delete a standalone form (and all its responses — the shareable link stops working)
