// GET /api/member/groups/:id/messages?before=<ISO>&limit=40
app.get("/api/member/groups/:id/messages", memberAuthMiddleware, gcReadLimit, async (req, res) => {
  try {
    const myId  = req.member.memberId;
    if (!myId) return res.status(403).json({ error: "Not authenticated" });
    const gid   = req.params.id;
    const limit = Math.min(parseInt(req.query.limit) || 40, 80);
    const before = req.query.before;
    const since  = req.query.since;

    // Verify membership
    const { data: mem } = await supabase.from("dm_group_members").select("member_id").eq("group_id", gid).eq("member_id", myId).maybeSingle();
    if (!mem) return res.status(403).json({ error: "Not in this group" });

    // NOTE: the last-read watermark is NOT stamped here anymore. Fetching or
    // polling this route only proves the client received the messages — it
    // does not prove anyone looked at them. See POST /api/member/groups/:id/read
    // below, which the client calls only after confirming the group panel is
    // open, visible, focused, and the messages actually rendered.

    // Pull nicknames for this group
    const { data: nickRows } = await supabase.from("dm_group_members").select("member_id, nickname").eq("group_id", gid);
    const nickMap = Object.fromEntries((nickRows || []).map(r => [r.member_id, r.nickname]));

    // SQL migration (run once in Supabase):
    //   ALTER TABLE dm_group_messages ADD COLUMN IF NOT EXISTS sender_device_id TEXT;
    // wrapped_keys was already JSONB; its keys just changed shape from plain
    // memberId to "${memberId}:${deviceId}" (client falls back to the old
    // memberId-only shape for messages sent before this migration).
    let q = supabase
      .from("dm_group_messages")
      .select("id, sender_id, body, created_at, edited_at, is_pinned, replied_to_id, replied_to_body, replied_to_sender, e2ee, ciphertext, wrapped_keys, sender_device_id, attachment_url, attachment_type, attachment_opacity")
      .eq("group_id", gid)
      .is("deleted_at", null)
      .order("created_at", { ascending: !!since })
      .limit(limit);

    if (before) q = q.lt("created_at", before);
    if (since)  q = q.gt("created_at", since);

    const { data: msgs, error } = await q;
    if (error) throw error;

    const reactionMap = await fetchReactionsFor((msgs || []).map(m => m.id), "group", myId);

    // Two-step: fetch sender profiles for all unique sender_ids
    const senderIds = [...new Set((msgs || []).map(m => m.sender_id).filter(Boolean))];
    const senderMap = {};
    if (senderIds.length) {
      const { data: senders, error: sErr } = await supabase
        .from("members")
        .select("id, name, photo")
        .in("id", senderIds);
      if (sErr) console.error("[groups/messages GET] senders:", sErr.message);
      (senders || []).forEach(s => { senderMap[s.id] = s; });
    }

    const result = (msgs || [])
      .sort((a, b) => new Date(a.created_at) - new Date(b.created_at))
      .map(m => {
        const isSystem = m.body?.startsWith('\x1fsys\x1f');
        const cleanBody = isSystem ? m.body.slice(6) : m.body;
        const sender = senderMap[m.sender_id] || {};
        return {
          id:               m.id,
          group_id:         gid,
          sender_id:        m.sender_id,
          sender_name:      nickMap[m.sender_id] || sender.name || "Member",
          sender_photo:     sender.photo || null,
          body:             cleanBody,
          sent_at:          m.created_at,
          edited_at:        m.edited_at || null,
          is_pinned:        m.is_pinned || false,
          is_system:        isSystem,
          replied_to_id:    m.replied_to_id    || null,
          replied_to_body:  m.replied_to_body  || null,
          replied_to_sender:m.replied_to_sender || null,
          reactions:        reactionMap[m.id] || [],
          // E2EE fields
          e2ee:             m.e2ee || false,
          ciphertext:       m.ciphertext || null,
          wrapped_keys:     m.wrapped_keys || null,
          sender_device_id: m.sender_device_id || null,
          // Attachments (image sharing)
          attachment_url:   m.attachment_url || null,
          attachment_type:  m.attachment_type || null,
          attachment_opacity: m.attachment_opacity ?? null,
        };
      });

    res.json(result);
  } catch (e) {
    console.error("[groups/messages GET]", e.message);
    res.status(500).json({ error: "Failed to load messages" });
  }
});

// ── GET /api/member/groups/:id/seen ────────────────────────────────────────────
// Returns every member's last-read watermark for this group. The client uses this
// to build a WhatsApp-style avatar stack under the most recent message: a member
// has "seen" that message if their last_read_at >= the message's created_at.
// Polled alongside reactions on the group poll tick — see gcPollTick.
app.get("/api/member/groups/:id/seen", memberAuthMiddleware, gcReadLimit, async (req, res) => {
  try {
    const myId = req.member.memberId;
    const gid  = req.params.id;
    const { data: mem } = await supabase.from("dm_group_members").select("member_id").eq("group_id", gid).eq("member_id", myId).maybeSingle();
    if (!mem) return res.status(403).json({ error: "Not in this group" });
    const { data } = await supabase.from("dm_group_reads").select("member_id, last_read_at").eq("group_id", gid);
    res.json(data || []);
  } catch (e) {
    console.error("[groups/seen GET]", e.message);
    res.json([]);
  }
});

// ── POST /api/member/groups/:id/read ─────────────────────────────────────────
// The ONLY place a group's last-read watermark gets stamped. Called
// exclusively by the client, only after confirming: the group panel is still
// the active conversation, document.visibilityState === "visible",
// document.hasFocus() is true, rendering has finished, and at least one
// message bubble actually exists in the DOM. Fetching/polling messages (GET
// /api/member/groups/:id/messages above) never touches this anymore.
// Per-member, so marking my own read status never affects anyone else's row
// in dm_group_reads (rule: group read status tracked per member).
app.post("/api/member/groups/:id/read", memberAuthMiddleware, async (req, res) => {
  try {
    const myId = req.member.memberId;
    const gid  = req.params.id;
    const { data: mem } = await supabase.from("dm_group_members").select("member_id").eq("group_id", gid).eq("member_id", myId).maybeSingle();
    if (!mem) return res.status(403).json({ error: "Not in this group" });

    const nowIso = new Date().toISOString();
    const { error } = await supabase
      .from("dm_group_reads")
      .upsert([{ group_id: gid, member_id: myId, last_read_at: nowIso }], { onConflict: "group_id,member_id" });
    if (error) throw error;
    res.json({ success: true, last_read_at: nowIso });
  } catch (e) {
    console.error("[groups/read POST]", e.message);
    res.status(500).json({ error: "Failed to mark read", code: e.code || null });
  }
});

// POST /api/member/groups/:id/messages  { body } — or E2EE: { e2ee: true, ciphertext, wrapped_keys, body: "" }
app.post("/api/member/groups/:id/messages", memberAuthMiddleware, gcWriteLimit, async (req, res) => {
  try {
    const myId = req.member.memberId;
    if (!myId) return res.status(403).json({ error: "Not authenticated" });
    const gid  = req.params.id;
    const { body: rawBody, replied_to_id, replied_to_body, replied_to_sender,
            e2ee, ciphertext, wrapped_keys, sender_device_id } = req.body || {};
    const body = (rawBody || "").trim();

    // E2EE validation
    if (e2ee) {
      if (!ciphertext || typeof ciphertext !== 'string' || ciphertext.length > 8000)
        return res.status(400).json({ error: "E2EE ciphertext missing or invalid" });
      if (!wrapped_keys || typeof wrapped_keys !== 'object' || Array.isArray(wrapped_keys))
        return res.status(400).json({ error: "E2EE wrapped_keys must be an object { memberId: wrappedKey }" });
    } else {
      if (!body || body.length > 2000) return res.status(400).json({ error: "Message body required (max 2000 chars)" });
    }

    // NOTE: Group chats are a private, unmoderated space (like DMs) — no profanity gate here.
    // (Profanity checks still apply to posts and comments, which are public-facing.)

    // Verify membership
    const { data: mem } = await supabase.from("dm_group_members").select("member_id, nickname").eq("group_id", gid).eq("member_id", myId).maybeSingle();
    if (!mem) return res.status(403).json({ error: "Not in this group" });

    const { data: sender } = await supabase.from("members").select("id, name, photo").eq("id", myId).maybeSingle();
    const safeReplyBody = await sanitizeReplyBody("dm_group_messages", replied_to_id, replied_to_body);

    const { data: msg, error } = await supabase
      .from("dm_group_messages")
      .insert([{
        group_id:          gid,
        sender_id:         myId,
        // E2EE: body is a sentinel; plaintext never stored server-side.
        // NOTE: must be non-empty — dm_group_messages.body has
        // CHECK (char_length(body) BETWEEN 1 AND 2000), so an empty string
        // here fails the insert (silently, from the client's perspective:
        // the message just never shows up). A single zero-width space
        // satisfies the constraint without leaking anything when rendered
        // (the client always decrypts ciphertext for e2ee messages and
        // never displays this field).
        body:              e2ee ? "\u200B" : body,
        replied_to_id:     replied_to_id     ? String(replied_to_id).slice(0, 36)    : null,
        replied_to_body:   safeReplyBody,
        replied_to_sender: replied_to_sender ? String(replied_to_sender).slice(0, 100): null,
        // E2EE columns
        e2ee:              e2ee ? true : false,
        ciphertext:        e2ee ? ciphertext : null,
        wrapped_keys:      e2ee ? wrapped_keys : null,
        sender_device_id:  e2ee ? (sender_device_id || null) : null,
      }])
      .select("id, sender_id, body, created_at, replied_to_id, replied_to_body, replied_to_sender, e2ee, ciphertext, wrapped_keys, sender_device_id")
      .single();
    if (error) throw error;

    // ── @mentions: parse plaintext body against group member names, notify ──
    // Skipped for E2EE messages — the server never sees plaintext for those,
    // so there's nothing to match against.
    if (!e2ee && body) {
      (async () => {
        try {
          const { data: memberRows } = await supabase
            .from("dm_group_members").select("member_id, nickname").eq("group_id", gid);
          const otherIds = (memberRows || []).map(r => r.member_id).filter(id => id !== myId);
          if (!otherIds.length) return;
          const { data: profiles } = await supabase
            .from("members").select("id, name").in("id", otherIds);
          const nickByI = {};
          (memberRows || []).forEach(r => { if (r.nickname) nickByI[r.member_id] = r.nickname; });

          // Build lookup: lowercased, no-space token -> member id
          const lookup = new Map();
          (profiles || []).forEach(p => {
            const candidates = [nickByI[p.id], p.name, (p.name || "").split(/\s+/)[0]].filter(Boolean);
            candidates.forEach(c => {
              const key = c.toLowerCase().replace(/\s+/g, "");
              if (key) lookup.set(key, p.id);
            });
          });

          const mentionTokens = [...body.matchAll(/@([A-Za-z0-9_.]{2,40})/g)].map(m => m[1].toLowerCase());
          const mentionedIds = [...new Set(mentionTokens.map(t => lookup.get(t)).filter(Boolean))];
          if (!mentionedIds.length) return;

          const { data: group } = await supabase.from("dm_group_chats").select("name").eq("id", gid).maybeSingle();
          const senderName = mem.nickname || sender?.name || "Member";
          const now = new Date().toISOString();
          const rows = mentionedIds.map(recipientId => ({
            member_id:   recipientId,
            type:        "group_mention",
            title:       `${senderName} mentioned you in ${group?.name || "a group"}`,
            body:        body.slice(0, 300),
            actor_id:    myId,
            actor_name:  senderName,
            actor_photo: sender?.photo || null,
            link_type:   "group",
            link_id:     gid,
            is_read:     false,
            created_at:  now,
          }));
          const { error: mentionErr } = await supabase.from("member_notifications").insert(rows);
          if (mentionErr) console.error("[group mention] insert:", mentionErr.message);
        } catch (mentionEx) {
          console.error("[group mention]", mentionEx.message);
        }
      })();
    }

    res.json({
      success: true,
      message: {
        id:               msg.id,
        group_id:         gid,
        sender_id:        myId,
        sender_name:      mem.nickname || sender?.name || "Member",
        sender_photo:     sender?.photo || null,
        body:             msg.body,
        sent_at:          msg.created_at,
        replied_to_id:    msg.replied_to_id    || null,
        replied_to_body:  msg.replied_to_body  || null,
        replied_to_sender:msg.replied_to_sender || null,
        reactions:        [],
        // E2EE fields
        e2ee:             msg.e2ee || false,
        ciphertext:       msg.ciphertext || null,
        wrapped_keys:     msg.wrapped_keys || null,
        sender_device_id: msg.sender_device_id || null,
      },
    });
  } catch (e) {
    console.error("[groups/messages POST]", e.message);
    res.status(500).json({ error: "Failed to send message" });
  }
});

// DELETE /api/member/groups/:id/messages/:msgId  — soft-delete own message
app.delete("/api/member/groups/:id/messages/:msgId", memberAuthMiddleware, gcWriteLimit, async (req, res) => {
  try {
    const myId  = req.member.memberId;
    const gid   = req.params.id;
    const msgId = req.params.msgId;
    const { data: msg } = await supabase.from("dm_group_messages").select("sender_id, group_id").eq("id", msgId).maybeSingle();
    if (!msg || msg.group_id !== gid) return res.status(404).json({ error: "Not found" });
    if (msg.sender_id !== myId) return res.status(403).json({ error: "Cannot delete another member's message" });
    await supabase.from("dm_group_messages").update({ deleted_at: new Date().toISOString(), body: "[deleted]" }).eq("id", msgId);
    res.json({ success: true });
  } catch (e) {
    res.status(500).json({ error: "Failed to delete message" });
  }
});

// PATCH /api/member/groups/:id/messages/:msgId — edit own message
// Body: { body } for plaintext, or { e2ee: true, body: "", ciphertext, wrapped_keys }
// for E2EE — same shape as POST .../messages, re-encrypted client-side for
// the new text against the current member list. Stamps edited_at so the
// client can render an "(edited)" tag, same pattern as the delete above.
//
// SQL migration (run once in Supabase):
//   ALTER TABLE dm_group_messages ADD COLUMN IF NOT EXISTS edited_at TIMESTAMPTZ;
app.patch("/api/member/groups/:id/messages/:msgId", memberAuthMiddleware, gcWriteLimit, async (req, res) => {
  try {
    const myId  = req.member.memberId;
    const gid   = req.params.id;
    const msgId = req.params.msgId;
    const { body: rawBody, e2ee, ciphertext, wrapped_keys, sender_device_id } = req.body || {};

    const { data: msg } = await supabase.from("dm_group_messages").select("sender_id, group_id, deleted_at").eq("id", msgId).maybeSingle();
    if (!msg || msg.group_id !== gid) return res.status(404).json({ error: "Not found" });
    if (msg.sender_id !== myId) return res.status(403).json({ error: "Cannot edit another member's message" });
    if (msg.deleted_at) return res.status(400).json({ error: "Can't edit a deleted message" });

    let update;
    if (e2ee) {
      if (!ciphertext || typeof ciphertext !== 'string' || ciphertext.length > 8000)
        return res.status(400).json({ error: "E2EE ciphertext missing or invalid" });
      if (!wrapped_keys || typeof wrapped_keys !== 'object' || Array.isArray(wrapped_keys))
        return res.status(400).json({ error: "E2EE wrapped_keys must be an object { \"memberId:deviceId\": wrappedKey }" });
      update = { body: "\u200B", e2ee: true, ciphertext, wrapped_keys, sender_device_id: sender_device_id || null, edited_at: new Date().toISOString() };
    } else {
      const trimmed = (rawBody || "").trim();
      if (!trimmed || trimmed.length > 2000) return res.status(400).json({ error: "Message body required (max 2000 chars)" });
      update = { body: trimmed, e2ee: false, ciphertext: null, wrapped_keys: null, sender_device_id: null, edited_at: new Date().toISOString() };
    }

    const { data: updated, error } = await supabase
      .from("dm_group_messages")
      .update(update)
      .eq("id", msgId)
      .select("id, body, edited_at, e2ee, ciphertext, wrapped_keys, sender_device_id")
      .single();
    if (error) throw error;

    res.json({ success: true, message: updated });
  } catch (e) {
    console.error("[groups/messages PATCH]", e.message);
    res.status(500).json({ error: "Failed to edit message" });
  }
});

// ── PATCH /api/member/groups/:id/messages/:msgId/wrapped-key ─────────────────
// MERGES a single (member_id, device_id) wrapped-key entry into an existing
// E2EE group message, rather than replacing the whole wrapped_keys map. Used
// by the client's auto-repair pass (gcAutoRewrapMissingKeys) to backfill
// devices that joined, rotated keys, or logged in after the message was
// originally sent. Only the original sender can patch their own message.
// NOTE: this route did not previously exist server-side — the client has
// been calling it since the multi-device migration and receiving 404s, so
// no group message auto-repair has actually been landing on the server yet.
app.patch("/api/member/groups/:id/messages/:msgId/wrapped-key", memberAuthMiddleware, gcWriteLimit, async (req, res) => {
  try {
    const myId  = req.member.memberId;
    const gid   = req.params.id;
    const msgId = req.params.msgId;
    const { member_id, device_id, wrapped_key } = req.body || {};
    if (!member_id || !device_id || typeof wrapped_key !== 'string' || !wrapped_key || wrapped_key.length > 8000)
      return res.status(400).json({ error: "member_id, device_id, wrapped_key required" });

    const { data: mem } = await supabase.from("dm_group_members").select("member_id").eq("group_id", gid).eq("member_id", myId).maybeSingle();
    if (!mem) return res.status(403).json({ error: "Not in this group" });

    const { data: msg } = await supabase
      .from("dm_group_messages")
      .select("sender_id, group_id, e2ee, wrapped_keys")
      .eq("id", msgId)
      .maybeSingle();
    if (!msg || msg.group_id !== gid) return res.status(404).json({ error: "Not found" });
    if (msg.sender_id !== myId) return res.status(403).json({ error: "Cannot patch another member's message" });
    if (!msg.e2ee) return res.status(400).json({ error: "Not an E2EE message" });

    const merged = { ...(msg.wrapped_keys || {}), [`${member_id}:${device_id}`]: wrapped_key };
    const { error } = await supabase
      .from("dm_group_messages")
      .update({ wrapped_keys: merged })
      .eq("id", msgId);
    if (error) throw error;
    res.json({ success: true, wrapped_keys: merged });
  } catch (e) {
    console.error("[groups/messages/:msgId/wrapped-key PATCH]", e.message);
    res.status(500).json({ error: "Failed to update wrapped key" });
  }
});

// POST /api/member/groups/:id/messages/image — send a photo to the group
// multipart/form-data: image=<file>, replied_to_id/body/sender?, opacity?
// SQL migration (run once in Supabase):
//   ALTER TABLE dm_group_messages ADD COLUMN IF NOT EXISTS attachment_url TEXT;
//   ALTER TABLE dm_group_messages ADD COLUMN IF NOT EXISTS attachment_type TEXT;
//   ALTER TABLE dm_group_messages ADD COLUMN IF NOT EXISTS attachment_opacity SMALLINT;
app.post("/api/member/groups/:id/messages/image", memberAuthMiddleware, gcWriteLimit,
  multer({ storage: multer.memoryStorage(), limits: { fileSize: 8 * 1024 * 1024 } }).single("image"),
  async (req, res) => {
    try {
      const myId = req.member.memberId;
      const gid  = req.params.id;
      const { replied_to_id, replied_to_body, replied_to_sender } = req.body || {};
      if (!req.file) return res.status(400).json({ error: "No image uploaded" });

      let opacity = parseInt(req.body?.opacity, 10);
      if (!Number.isFinite(opacity)) opacity = 100;
      opacity = Math.max(15, Math.min(100, opacity));

      const { data: mem } = await supabase.from("dm_group_members").select("member_id, nickname").eq("group_id", gid).eq("member_id", myId).maybeSingle();
      if (!mem) return res.status(403).json({ error: "Not in this group" });

      const resized = await sharp(req.file.buffer)
        .resize(1280, 1280, { fit: "inside", withoutEnlargement: true })
        .jpeg({ quality: 82 })
        .toBuffer();

      const uploadResult = await new Promise((resolve, reject) => {
        cloudinary.uploader.upload_stream(
          { folder: "kfs-group-attachments", resource_type: "image" },
          (err, result) => err ? reject(err) : resolve(result)
        ).end(resized);
      });

      const { data: sender } = await supabase.from("members").select("id, name, photo").eq("id", myId).maybeSingle();
      const safeReplyBody = await sanitizeReplyBody("dm_group_messages", replied_to_id, replied_to_body);

      const { data: msg, error } = await supabase
        .from("dm_group_messages")
        .insert([{
          group_id:          gid,
          sender_id:         myId,
          body:              "📷 Photo",
          replied_to_id:     replied_to_id     ? String(replied_to_id).slice(0, 36)    : null,
          replied_to_body:   safeReplyBody,
          replied_to_sender: replied_to_sender ? String(replied_to_sender).slice(0, 100): null,
          attachment_url:    uploadResult.secure_url,
          attachment_type:   "image",
          attachment_opacity: opacity,
        }])
        .select("id, sender_id, body, created_at, replied_to_id, replied_to_body, replied_to_sender, attachment_url, attachment_type, attachment_opacity")
        .single();
      if (error) throw error;

      res.json({
        success: true,
        message: {
          id:                msg.id,
          group_id:          gid,
          sender_id:         myId,
          sender_name:       mem.nickname || sender?.name || "Member",
          sender_photo:      sender?.photo || null,
          body:              msg.body,
          sent_at:           msg.created_at,
          replied_to_id:     msg.replied_to_id    || null,
          replied_to_body:   msg.replied_to_body  || null,
          replied_to_sender: msg.replied_to_sender || null,
          reactions:         [],
          e2ee:              false,
          attachment_url:    msg.attachment_url,
          attachment_type:   msg.attachment_type,
          attachment_opacity: msg.attachment_opacity ?? opacity,
        },
      });
    } catch (e) {
      console.error("[groups/messages/image POST]", e.message);
      res.status(500).json({ error: "Failed to send image" });
    }
  }
);

// POST /api/member/groups/:id/messages/:msgId/react  { emoji }
// Toggle: same emoji again → remove, different → switch, none → add.
app.post("/api/member/groups/:id/messages/:msgId/react", memberAuthMiddleware, reactionLimit, async (req, res) => {
  try {
    const myId  = req.member.memberId;
    const gid   = req.params.id;
    const msgId = req.params.msgId;
    const emoji = String(req.body?.emoji || "").trim().slice(0, 8);
    if (!emoji) return res.status(400).json({ error: "emoji required" });

    const { data: mem } = await supabase.from("dm_group_members").select("member_id").eq("group_id", gid).eq("member_id", myId).maybeSingle();
    if (!mem) return res.status(403).json({ error: "Not in this group" });

    const { data: msg } = await supabase.from("dm_group_messages").select("id, group_id").eq("id", msgId).eq("group_id", gid).maybeSingle();
    if (!msg) return res.status(404).json({ error: "Message not found" });

    await toggleMessageReaction(msgId, "group", myId, emoji);
    const reactionMap = await fetchReactionsFor([msgId], "group", myId);
    res.json({ success: true, reactions: reactionMap[msgId] || [] });
  } catch (e) {
    console.error("[groups/react]", e.message);
    res.status(500).json({ error: "Failed to react" });
  }
});

// ── GET /api/member/messages/reactions?chat_type=dm|group&ids=a,b,c ──────────
// Lightweight reaction-only refresh for messages already rendered on screen —
// piggybacked on the existing DM/group poll tick so a reaction someone else
// just added shows up within one poll cycle, without re-fetching/re-rendering
// the whole message list.
app.get("/api/member/messages/reactions", memberAuthMiddleware, reactionLimit, async (req, res) => {
  try {
    const myId     = req.member.memberId;
    const chatType = req.query.chat_type;
    const ids      = String(req.query.ids || "").split(",").map(s => s.trim()).filter(Boolean).slice(0, 100);
    if (!["dm", "group"].includes(chatType) || !ids.length) return res.json({});

    let allowedIds = [];
    if (chatType === "dm") {
      // DM messages are stored as member_notifications rows with link_type='dm'.
      // The caller must be either the actor (sender) or the recipient (member_id).
      const { data } = await supabase
        .from("member_notifications")
        .select("id, actor_id, member_id")
        .eq("link_type", "dm")
        .in("id", ids);
      allowedIds = (data || [])
        .filter(r => r.actor_id === myId || r.member_id === myId)
        .map(r => r.id);
    } else {
      const { data } = await supabase.from("dm_group_messages").select("id, group_id").in("id", ids);
      const groupIds = [...new Set((data || []).map(r => r.group_id))];
      const { data: memRows } = groupIds.length
        ? await supabase.from("dm_group_members").select("group_id").eq("member_id", myId).in("group_id", groupIds)
        : { data: [] };
      const myGroups = new Set((memRows || []).map(r => r.group_id));
      allowedIds = (data || []).filter(r => myGroups.has(r.group_id)).map(r => r.id);
    }

    const map = await fetchReactionsFor(allowedIds, chatType, myId);
    res.json(map);
  } catch (e) {
    console.error("[messages/reactions GET]", e.message);
    res.json({});
  }
});

// ─────────────────────────────────────────────────────────────────────────────
// SECTION — Typing indicators (DM + group)
//
// Kept in an in-memory Map rather than a DB table: typing state is ephemeral
// (a few seconds of relevance, refreshed constantly while someone types) and
// never needs to survive a restart or be queried historically — writing it to
// Supabase on every keystroke would be pure overhead. Piggybacks on the same
// poll-tick pattern the rest of DM/group chat already uses (reactions, seen-by,
// read receipts), so "X is typing…" shows up within one poll cycle.
//
// If this app is ever run across multiple Node instances behind a load
// balancer, swap this Map for a shared store (Redis, or a Supabase table with
// a short TTL sweep) — a single instance is assumed here, consistent with the
// rest of the in-memory state in this file (e.g. lockout tracking).
// ─────────────────────────────────────────────────────────────────────────────
const _typingState = new Map(); // conv_key -> Map(member_id -> { name, at })
const TYPING_TTL_MS = 6000; // a typing signal is considered stale after 6s

const typingLimit = rateLimit({ windowMs: 10_000, max: 40, standardHeaders: true, legacyHeaders: false });

// POST /api/member/typing  { conv_key, conv_type: 'dm'|'group' }
// Called by the client every ~2s while the user has text in the composer.
app.post("/api/member/typing", memberAuthMiddleware, typingLimit, async (req, res) => {
  try {
    const myId = req.member.memberId;
    const { conv_key, conv_type } = req.body || {};
    if (!conv_key || !["dm", "group"].includes(conv_type)) return res.status(400).json({ error: "conv_key and conv_type required" });

    // Verify membership before recording a typing signal, same trust boundary
    // as reading messages in that conversation.
    if (conv_type === "dm") {
      const parts = String(conv_key).split(":");
      if (parts.length !== 2 || !parts.includes(myId)) return res.status(403).json({ error: "Forbidden" });
    } else {
      const { data: mem } = await supabase.from("dm_group_members").select("member_id").eq("group_id", conv_key).eq("member_id", myId).maybeSingle();
      if (!mem) return res.status(403).json({ error: "Not in this group" });
    }

    const { data: me } = await supabase.from("members").select("name").eq("id", myId).maybeSingle();
    if (!_typingState.has(conv_key)) _typingState.set(conv_key, new Map());
    _typingState.get(conv_key).set(myId, { name: me?.name || "Someone", at: Date.now() });

    res.json({ success: true });
  } catch (e) {
    console.error("[typing POST]", e.message);
    res.json({ success: false });
  }
});

// GET /api/member/typing?conv_key=...&conv_type=dm|group
// Returns everyone (other than me) whose last typing signal is still fresh.
app.get("/api/member/typing", memberAuthMiddleware, typingLimit, async (req, res) => {
  try {
    const myId = req.member.memberId;
    const { conv_key, conv_type } = req.query || {};
    if (!conv_key || !["dm", "group"].includes(conv_type)) return res.json([]);

    const bucket = _typingState.get(conv_key);
    if (!bucket) return res.json([]);

    const now = Date.now();
    const typers = [];
    for (const [memberId, info] of bucket.entries()) {
      if (memberId === myId) continue;
      if (now - info.at > TYPING_TTL_MS) { bucket.delete(memberId); continue; }
      typers.push({ member_id: memberId, name: info.name });
    }
    res.json(typers);
  } catch (e) {
    console.error("[typing GET]", e.message);
    res.json([]);
  }
});

// ── init check ────────────────────────────────────────────────────────────────
// ── SQL MIGRATION REQUIRED for pin + group photo features ─────────────────────
// Run once in Supabase SQL editor:
//
//   ALTER TABLE dm_group_chats ADD COLUMN IF NOT EXISTS photo_url TEXT;
//   ALTER TABLE dm_group_messages ADD COLUMN IF NOT EXISTS is_pinned BOOLEAN NOT NULL DEFAULT FALSE;
//   CREATE INDEX IF NOT EXISTS idx_group_msgs_pinned ON dm_group_messages(group_id, is_pinned) WHERE is_pinned = TRUE;
//
// ── SQL MIGRATION REQUIRED for read receipts / seen indicators ────────────────
// Run once in Supabase SQL editor:
//
//   -- DMs: delivered→seen distinction (WhatsApp-style double ticks)
//   ALTER TABLE member_notifications ADD COLUMN IF NOT EXISTS delivered_at TIMESTAMPTZ;
//   ALTER TABLE member_notifications ADD COLUMN IF NOT EXISTS read_at TIMESTAMPTZ;
//
//   -- Groups: one row per (group, member) holding a last-read watermark, rather
//   -- than a flag per message — this is how WhatsApp/Slack-style "seen by" scales:
//   -- a member has seen a message if their last_read_at >= that message's created_at.
//   CREATE TABLE IF NOT EXISTS dm_group_reads (
//     group_id     UUID NOT NULL REFERENCES dm_group_chats(id) ON DELETE CASCADE,
//     member_id    UUID NOT NULL REFERENCES members(id) ON DELETE CASCADE,
//     last_read_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
//     PRIMARY KEY (group_id, member_id)
//   );
//   CREATE INDEX IF NOT EXISTS idx_grp_reads_group ON dm_group_reads(group_id);
//   ALTER TABLE dm_group_reads DISABLE ROW LEVEL SECURITY; -- server uses service_role key
//
// ─────────────────────────────────────────────────────────────────────────────
async function initSocialDB() {
  const tables = [
    "member_blocks",
    "member_nicknames",
    "dm_group_chats",
    "dm_group_members",
    "dm_group_messages",
    "message_reactions",
    "dm_group_reads",
  ];
  let allOk = true;
  for (const t of tables) {
    const { error } = await supabase.from(t).select("*", { count: "exact", head: true }).limit(1);
    if (error?.code === "42P01") {
      console.warn(`[social] Table "${t}" not found — run MA-35 SQL migration in Supabase`);
      allOk = false;
    } else if (error) {
      console.warn(`[social] Table "${t}" check failed: ${error.message}`);
      allOk = false;
    }
  }
  if (allOk) console.log("[social] All social tables OK");
}

// Catch unhandled promise rejections — log them, don't crash
process.on('unhandledRejection', (reason) => {
  console.error('[unhandledRejection]', reason);
});

// Catch uncaught exceptions — log and exit gracefully (process manager will restart)
process.on('uncaughtException', (err) => {
  console.error('[uncaughtException]', err);
  process.exit(1);
});


// ── POST /api/member/kfs-broadcast ───────────────────────────────────────────
// Admin-only: DM from the KFS sentinel account to all or specific members.
// Body: { body: string, target?: "all"|"member_ids", member_ids?: string[] }
app.post("/api/member/kfs-broadcast", memberAuthMiddleware, async (req, res) => {
  try {
    const myId = req.member.memberId;
    const { data: member } = await supabase
      .from("members").select("id, name, role, is_admin").eq("id", myId).maybeSingle();
    if (!member) return res.status(403).json({ error: "Not authenticated" });

    const allowedRoles = ["admin", "master_admin", "kfs_admin"];
    const isAdmin = member.is_admin === true ||
      allowedRoles.includes(String(member.role || "").toLowerCase());
    if (!isAdmin) return res.status(403).json({ error: "Admin only" });

    const { body, target = "all", member_ids } = req.body || {};
    if (!body || !String(body).trim())
      return res.status(400).json({ error: "Message body is required" });

    // Resolve KFS sentinel member ID
    const { data: kfsSetting } = await supabase
      .from("settings").select("value").eq("key", "kfs_admin_member_id").maybeSingle();
    let kfsMemberId = kfsSetting?.value || null;
    if (!kfsMemberId) {
      const { data: kfsMember } = await supabase
        .from("members").select("id").ilike("name", "KFS%").limit(1).maybeSingle();
      kfsMemberId = kfsMember?.id || null;
    }
    if (!kfsMemberId)
      return res.status(400).json({
        error: "No KFS sentinel member found. Create a member named 'KFS' or set kfs_admin_member_id in settings.",
      });

    // Collect recipients
    let recipientIds = [];
    if (target === "member_ids" && Array.isArray(member_ids) && member_ids.length) {
      recipientIds = member_ids.filter(id => typeof id === "string" && id.length > 0);
    } else {
      // NOTE: members has no is_active column — use deleted_at IS NULL,
      // the same liveness check the real DM-send route uses.
      const { data: allMembers } = await supabase
        .from("members").select("id").is("deleted_at", null);
      recipientIds = (allMembers || []).map(m => m.id).filter(id => id !== kfsMemberId);
    }

    if (!recipientIds.length)
      return res.status(400).json({ error: "No recipients found" });

    const msgBody = String(body).trim().slice(0, 2000);
    const now     = new Date().toISOString();
    let   sent    = 0;
    const BATCH   = 50;

    // Fetch KFS sentinel's display info for the notification snapshot
    const { data: kfsMember } = await supabase
      .from("members").select("id, name, photo").eq("id", kfsMemberId).maybeSingle();

    for (let i = 0; i < recipientIds.length; i += BATCH) {
      const batch = recipientIds.slice(i, i + BATCH);
      const rows  = batch.map(recipientId => ({
        member_id:   recipientId,
        type:        "dm",
        title:       `Message from ${kfsMember?.name || "KFS"}`,
        body:        msgBody,
        actor_id:    kfsMemberId,
        actor_name:  kfsMember?.name  || "KFS",
        actor_photo: kfsMember?.photo || KFS_SENTINEL_LOGO_URL,
        link_type:   "dm",
        link_id:     dmConvKey(kfsMemberId, recipientId),
        is_read:     false,
        created_at:  now,
      }));
      const { error: insErr } = await supabase.from("member_notifications").insert(rows);
      if (!insErr) sent += batch.length;
      else console.error("[kfs-broadcast] batch insert error:", insErr.message, insErr.details || "");
    }

    logActivity(myId, member.name || "Admin", "kfs_broadcast", "member_notifications",
      `Sent to ${sent} member(s)`).catch(() => {});
    res.json({ success: true, sent });
  } catch (e) {
    console.error("[kfs-broadcast]", e.message);
    res.status(500).json({ error: "Internal server error" });
  }
});

