// ── START ─────────────────────────────────────────────────────────────────────
app.listen(PORT, async () => {
  console.log(`KFS server running on port ${PORT}`);
  await initDB();
  await initMemberDB();      // ← member portal init
  await loadMemberViolations(); // ← restore mutes/bans across restarts
  await initStudioWallDB();  // ← studio wall table check
  await initSocialDB();      // ← social: blocks, nicknames, group chats
  await loadRevokedTokens();
  await loadActiveLockouts();
  console.log("DB initialized");

  // ── 2FA Enforcement: delete non-master admins without 2FA after 48h ──
  async function enforce2FAPolicy() {
    try {
      const cutoff = new Date(Date.now() - 48 * 60 * 60 * 1000).toISOString();
      const { data: stale, error } = await supabase
        .from("admins")
        .select("id, name, username, created_at")
        .eq("totp_enabled", false)
        .neq("role", "master")
        .lt("created_at", cutoff);
      if (error) { console.error("[2fa-enforce] query error:", error.message); return; }
      if (!stale || stale.length === 0) return;
      for (const admin of stale) {
        await supabase.from("admins").delete().eq("id", admin.id);
        await logActivity("system", "System", "delete", "admin",
          `${admin.name} (${admin.username}) — auto-deleted: 2FA not enabled within 48h`);
        console.log(`[2fa-enforce] Deleted admin "${admin.username}" — no 2FA after 48h`);
      }
    } catch (e) {
      console.error("[2fa-enforce] error:", e.message);
    }
  }
  await enforce2FAPolicy();
  setInterval(enforce2FAPolicy, 60 * 60 * 1000);

  // ── Phase 2 — "The Network": weekly/all-time leaderboard refresh ──
  // Recomputes via the compute_leaderboard() Postgres function (see
  // phase2_leaderboard_function.sql) so the read endpoint never has to
  // aggregate reaction history live.
  await refreshLeaderboards();
  setInterval(refreshLeaderboards, 30 * 60 * 1000);

  // ── Engagement Analytics: recompute post momentum + daily creator metrics ──
  // Keeps /api/admin/analytics/viral-content fast (reads a precomputed table
  // instead of aggregating reactions/comments live on every dashboard hit).
  async function refreshEngagementAnalytics() {
    try {
      const since24h = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
      const since1h  = new Date(Date.now() - 60 * 60 * 1000).toISOString();

      const { data: recentPosts, error: postsErr } = await supabase
        .from("member_projects")
        .select("id, member_id, created_at")
        .is("deleted_at", null)
        .gte("created_at", new Date(Date.now() - 14 * 24 * 60 * 60 * 1000).toISOString()) // only score posts from the last 14 days
        .limit(500);
      if (postsErr) { console.error("[engagement-analytics] posts query error:", postsErr.message); return; }
      if (!recentPosts || !recentPosts.length) return;

      const postIds = recentPosts.map(p => p.id);
      const [{ data: reactions24h }, { data: reactions1h }, { data: comments24h }, { data: comments1h }] = await Promise.all([
        supabase.from("project_reactions").select("project_id, created_at").in("project_id", postIds).gte("created_at", since24h),
        supabase.from("project_reactions").select("project_id").in("project_id", postIds).gte("created_at", since1h),
        supabase.from("project_comments").select("project_id, created_at").in("project_id", postIds).is("deleted_at", null).gte("created_at", since24h),
        supabase.from("project_comments").select("project_id").in("project_id", postIds).is("deleted_at", null).gte("created_at", since1h),
      ]);

      const countBy = (rows, key = "project_id") => {
        const m = {};
        for (const r of rows || []) m[r[key]] = (m[r[key]] || 0) + 1;
        return m;
      };
      const r24 = countBy(reactions24h), r1 = countBy(reactions1h);
      const c24 = countBy(comments24h), c1 = countBy(comments1h);

      const rows = recentPosts.map(p => {
        const reactions_last_24h = r24[p.id] || 0;
        const reactions_last_1h  = r1[p.id]  || 0;
        const comments_last_24h  = c24[p.id] || 0;
        const comments_last_1h   = c1[p.id]  || 0;
        const ageHours = Math.max(1, (Date.now() - new Date(p.created_at).getTime()) / 3600000);
        const baseline_per_hour = (reactions_last_24h + comments_last_24h) / Math.min(24, ageHours);
        const velocity = reactions_last_1h + comments_last_1h; // engagement in the last hour
        const velocity_change_pct = baseline_per_hour > 0
          ? Math.round(((velocity - baseline_per_hour) / baseline_per_hour) * 100)
          : (velocity > 0 ? 100 : 0);
        // Viral/momentum score: weighted blend of velocity, acceleration (change %), and raw 24h engagement.
        const viral_score = Math.min(100, Math.round(
          velocity * 8 +
          Math.max(0, velocity_change_pct) * 0.15 +
          (reactions_last_24h + comments_last_24h) * 0.5
        ));
        // Anomaly score is DELIBERATELY separate from viral_score — a legitimately
        // viral post should not be flagged. This only rises when velocity is both
        // extreme AND wildly discontinuous from the post's own recent baseline.
        const anomaly_score = baseline_per_hour > 0.5 && velocity > baseline_per_hour * 15
          ? Math.min(100, Math.round((velocity / baseline_per_hour) * 2))
          : 0;
        return {
          project_id: p.id, reactions_last_1h, reactions_last_24h, comments_last_1h, comments_last_24h,
          baseline_per_hour: Number(baseline_per_hour.toFixed(3)), velocity: Number(velocity.toFixed(3)),
          velocity_change_pct, viral_score, anomaly_score, updated_at: new Date().toISOString(),
        };
      });

      const { error: upsertErr } = await supabase.from("post_momentum").upsert(rows, { onConflict: "project_id" });
      if (upsertErr) console.error("[engagement-analytics] upsert error:", upsertErr.message);
      else console.log(`[engagement-analytics] Refreshed momentum for ${rows.length} posts`);
    } catch (e) {
      console.error("[engagement-analytics] error:", e.message);
    }
  }
  await refreshEngagementAnalytics();
  setInterval(refreshEngagementAnalytics, 10 * 60 * 1000); // every 10 min — dashboard reads are cached 60s on top of this
});

// ── /forms/:slug  (e.g. /forms/alumni-meet-feedback-4f2a) ───────────────────
// Standalone forms are not tied to any event — this is their canonical,
// shareable, crawlable URL. Serves the SPA with real OG tags for link
// previews; the client router (checkRoute) renders the actual fillable
// form full-page once index.html loads.
app.get("/forms/:slug", async (req, res) => {
  try {
    const { data: f } = await supabasePublic
      .from("standalone_forms")
      .select("slug,title,description,is_open")
      .eq("slug", req.params.slug)
      .maybeSingle();

    if (!f) {
      // Unknown slug — serve SPA without special OG; client shows its own "not found" state.
      return res.sendFile(path.join(__dirname, "public", "index.html"));
    }

    const pageUrl = `https://kiitfilmsociety.in/forms/${f.slug}`;
    return serveWithOg(res, {
      title: f.title ? `${f.title} — KFS` : "Form — KFS",
      description: f.description || `Fill out "${f.title || "this form"}" for KIIT Film Society.`,
      imageUrl: null,
      url: pageUrl,
      type: "website",
    });
  } catch (err) {
    console.error("[share/forms]", err.message);
    res.sendFile(path.join(__dirname, "public", "index.html"));
  }
});

// ── CATCH-ALL ─────────────────────────────────────────────────────────────────
app.get("*", (req, res) => {
  const p = req.path.replace(/\/+$/, "") || "/";
  // Known client-side pages: serve the shell with their OWN canonical.
  if (SPA_PUBLIC_ROUTES.has(p.toLowerCase())) return serveSpaShell(req, res);
  // Anything else is a URL that does not exist. Return a real 404 status (the SPA
  // still shows its friendly 404 screen) and keep it out of the index.
  return serveSpaShell(req, res, { status: 404, noindex: true, title: "Page not found — KIIT Film Society" });
});

// ── SUPABASE KEEPALIVE ────────────────────────────────────────────────────────
// Ping every 29 minutes to prevent the connection from going idle.
// Supabase times out idle connections at 30 min — this stays safely inside that window.
setInterval(
  async () => {
    try {
      await supabasePublic.from("settings").select("key", { count: "exact", head: true }).limit(1); // zero egress bytes
      // Silent success — log only on failure
    } catch (e) {
      console.error("Supabase keepalive failed:", e.message);
    }
  },
  1000 * 60 * 29,
);

// Purge stale E2EE device rows — run once per day.
//   - Devices revoked more than 30 days ago: safe to hard-delete, nothing
//     references them anymore (messages store the key material inline in
//     ciphers/wrapped_keys, not a foreign key to this table).
//   - Devices never revoked but not seen in 180+ days: almost certainly an
//     abandoned browser/uninstalled app. Removing them keeps encryptDm/
//     encryptGroup from wasting effort fanning out to dead devices, and
//     keeps the "Manage devices" list meaningful. This does NOT revoke
//     access to anything retroactively — it just stops future messages
//     from being encrypted for a device nobody uses anymore.
setInterval(
  async () => {
    try {
      const revokedCutoff = new Date();
      revokedCutoff.setDate(revokedCutoff.getDate() - 30);
      await supabase
        .from("member_e2ee_devices")
        .delete()
        .not("revoked_at", "is", null)
        .lt("revoked_at", revokedCutoff.toISOString());

      const staleCutoff = new Date();
      staleCutoff.setDate(staleCutoff.getDate() - 180);
      await supabase
        .from("member_e2ee_devices")
        .delete()
        .is("revoked_at", null)
        .lt("last_seen_at", staleCutoff.toISOString());
    } catch (e) {
      console.error("[e2ee devices cleanup]", e.message);
    }
  },
  1000 * 60 * 60 * 24,
); // every 24h

// Trim old page_view rows older than 90 days — run once per day
setInterval(
  async () => {
    try {
      const cutoff = new Date();
      cutoff.setDate(cutoff.getDate() - 90);
      await supabasePublic
        .from("page_views")
        .delete()
        .lt("date", cutoff.toISOString().slice(0, 10));
    } catch (e) {
      console.error("[page_views trim]", e.message);
    }
  },
  1000 * 60 * 60 * 24,
); // every 24h

// ── GLOBAL ERROR HANDLER ──────────────────────────────────────────────────────
// Catches any error passed via next(err) or thrown inside async route handlers
// that weren't caught locally. Logs the real error server-side, sends a safe
// generic message to the client — never leaks stack traces or internals.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  console.error(`[unhandled] ${req.method} ${req.path}`, err);
  if (res.headersSent) return next(err);
  // Multer errors (bad file type, file too large, unexpected field, etc.)
  // don't carry an err.status — without this they'd fall through to the
  // generic 500 branch below and hide the real reason from the client.
  if (err instanceof multer.MulterError || err.code === 'INVALID_FILE_TYPE') {
    return res.status(400).json({ error: err.message || 'Invalid upload' });
  }
  const status = typeof err.status === 'number' ? err.status : 500;
  res.status(status).json({ error: status < 500 ? (err.message || 'Bad request') : 'Internal server error' });
});

// ─────────────────────────────────────────────────────────────────────────────
// SECTION MA-35 — Social: Block/Unblock · Nicknames · Group Chats
//
// SQL migration (run once in Supabase):
//
//   -- Block list
//   CREATE TABLE IF NOT EXISTS member_blocks (
//     blocker_id  UUID NOT NULL REFERENCES members(id) ON DELETE CASCADE,
//     blocked_id  UUID NOT NULL REFERENCES members(id) ON DELETE CASCADE,
//     created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
//     PRIMARY KEY (blocker_id, blocked_id)
//   );
//   CREATE INDEX IF NOT EXISTS idx_blocks_blocker ON member_blocks(blocker_id);
//   CREATE INDEX IF NOT EXISTS idx_blocks_blocked ON member_blocks(blocked_id);
//
//   -- Nicknames (one per direction — giver → target)
//   CREATE TABLE IF NOT EXISTS member_nicknames (
//     giver_id    UUID NOT NULL REFERENCES members(id) ON DELETE CASCADE,
//     target_id   UUID NOT NULL REFERENCES members(id) ON DELETE CASCADE,
//     nickname    TEXT NOT NULL CHECK (char_length(nickname) BETWEEN 1 AND 40),
//     updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
//     PRIMARY KEY (giver_id, target_id)
//   );
//
//   -- Group chats
//   CREATE TABLE IF NOT EXISTS dm_group_chats (
//     id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
//     name         TEXT NOT NULL CHECK (char_length(name) BETWEEN 1 AND 60),
//     created_by   UUID NOT NULL REFERENCES members(id) ON DELETE CASCADE,
//     created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW()
//   );
//   CREATE TABLE IF NOT EXISTS dm_group_members (
//     group_id    UUID NOT NULL REFERENCES dm_group_chats(id) ON DELETE CASCADE,
//     member_id   UUID NOT NULL REFERENCES members(id) ON DELETE CASCADE,
//     nickname    TEXT,                -- group-scoped nickname for this member (visible to all)
//     joined_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
//     PRIMARY KEY (group_id, member_id)
//   );
//   CREATE TABLE IF NOT EXISTS dm_group_messages (
//     id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
//     group_id    UUID NOT NULL REFERENCES dm_group_chats(id) ON DELETE CASCADE,
//     sender_id   UUID NOT NULL REFERENCES members(id) ON DELETE CASCADE,
//     body        TEXT NOT NULL CHECK (char_length(body) BETWEEN 1 AND 2000),
//     deleted_at  TIMESTAMPTZ,
//     is_deleted  BOOLEAN NOT NULL DEFAULT FALSE,
//     replied_to_id     UUID REFERENCES dm_group_messages(id) ON DELETE SET NULL,
//     replied_to_body   TEXT,
//     replied_to_sender TEXT,
//     created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
//   );
//   -- member_notifications (DMs) also needs replied_to columns:
//   -- ALTER TABLE member_notifications ADD COLUMN IF NOT EXISTS replied_to_id UUID;
//   -- ALTER TABLE member_notifications ADD COLUMN IF NOT EXISTS replied_to_body TEXT;
//   -- ALTER TABLE member_notifications ADD COLUMN IF NOT EXISTS replied_to_sender TEXT;
//   CREATE INDEX IF NOT EXISTS idx_grp_msgs_group ON dm_group_messages(group_id, created_at);
//   CREATE INDEX IF NOT EXISTS idx_grp_members_member ON dm_group_members(member_id);
//
//   -- Message reactions (Instagram-style — one reaction per member per message,
//   -- shared by both DMs and group chats via the chat_type discriminator)
//   CREATE TABLE IF NOT EXISTS message_reactions (
//     id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
//     chat_type   TEXT NOT NULL CHECK (chat_type IN ('dm','group')),
//     message_id  UUID NOT NULL,
//     member_id   UUID NOT NULL REFERENCES members(id) ON DELETE CASCADE,
//     emoji       TEXT NOT NULL CHECK (char_length(emoji) BETWEEN 1 AND 8),
//     created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
//     UNIQUE (chat_type, message_id, member_id)
//   );
//   CREATE INDEX IF NOT EXISTS idx_msg_reactions_msg ON message_reactions(chat_type, message_id);
//   ALTER TABLE message_reactions DISABLE ROW LEVEL SECURITY; -- server uses service_role key
// ─────────────────────────────────────────────────────────────────────────────

// reactionLimit — defined earlier, near first use

// ── Message reactions — shared helpers (DM + group) ───────────────────────────
// One reaction per member per message (tap a new emoji to switch, tap your
// current one again to remove — same toggle pattern as Studio Wall reactions).

/**
 * Fetch + aggregate reactions for a batch of message ids.
 * Returns { [messageId]: [{ emoji, count, mine }, ...] }, sorted by count desc.
 */
async function fetchReactionsFor(messageIds, chatType, myId) {
  if (!messageIds || !messageIds.length) return {};
  const { data, error } = await supabase
    .from("message_reactions")
    .select("message_id, member_id, emoji")
    .eq("chat_type", chatType)
    .in("message_id", messageIds);
  if (error) {
    if (error.code !== "42P01") console.error("[reactions] fetch:", error.message);
    return {};
  }
  const byMsg = {};
  (data || []).forEach(r => {
    const bucket = (byMsg[r.message_id] = byMsg[r.message_id] || {});
    const slot   = (bucket[r.emoji] = bucket[r.emoji] || { emoji: r.emoji, count: 0, mine: false });
    slot.count++;
    if (r.member_id === myId) slot.mine = true;
  });
  const out = {};
  Object.keys(byMsg).forEach(mid => {
    out[mid] = Object.values(byMsg[mid]).sort((a, b) => b.count - a.count);
  });
  return out;
}

/** Toggle a member's reaction on a message: same emoji → remove, different → switch, none → add. */
async function toggleMessageReaction(messageId, chatType, myId, emoji) {
  const { data: existing } = await supabase
    .from("message_reactions")
    .select("id, emoji")
    .eq("chat_type", chatType).eq("message_id", messageId).eq("member_id", myId)
    .maybeSingle();
  if (existing && existing.emoji === emoji) {
    await supabase.from("message_reactions").delete().eq("id", existing.id);
  } else if (existing) {
    await supabase.from("message_reactions").update({ emoji }).eq("id", existing.id);
  } else {
    await supabase.from("message_reactions").insert([{ chat_type: chatType, message_id: messageId, member_id: myId, emoji }]);
  }
}
